(function(){
'use strict';
const E=CoreWarEngine,D=OgunData,C=OgunChallenges,T=OgunCompetition,S=OgunSession,L=OgunLive,W=OgunWorkshop,root=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);let storageIssue=false;
const defaults={prefs:{...S.DEFAULTS,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches},custom:[],solved:{},lessons:[],history:[],tournaments:[],draft:{a:D.warriors[0].code,b:D.warriors[1].code}};
function load(){try{const d=JSON.parse(localStorage.getItem('ogun-v1')||'null');return d?sanitize(d):structuredClone(defaults);}catch{storageIssue=true;return structuredClone(defaults);}}
function sanitize(d){
 if(!d||typeof d!=='object'||Array.isArray(d))throw new Error('Archivo de datos inválido.');
 const out=structuredClone(defaults);out.prefs=S.sanitize(d.prefs);
 if(Array.isArray(d.custom)){if(d.custom.length>100)throw new Error('Máximo 100 guerreros guardados.');out.custom=d.custom.map((w,i)=>{if(typeof w.code!=='string'||w.code.length>100000)throw new Error('Código de guerrero inválido.');const compiled=E.compileWarrior(w.code);return{id:'custom-'+i+'-'+Date.now(),name:String(w.name||compiled.metadata.name).slice(0,80),type:'Personal',description:'Tu guerrero guardado.',code:w.code,level:'Personal'};});}
 if(d.draft){for(const k of ['a','b'])if(typeof d.draft[k]==='string'&&d.draft[k].length<=100000)out.draft[k]=d.draft[k];}
 if(d.solved&&typeof d.solved==='object'&&!Array.isArray(d.solved))for(const [id,v]of Object.entries(d.solved).slice(-2000))if(typeof v==='boolean')out.solved[id]=v;
 if(Array.isArray(d.lessons))out.lessons=[...new Set(d.lessons.filter(n=>Number.isInteger(n)&&n>=0&&n<D.lessons.length))];
 if(Array.isArray(d.history))out.history=d.history.filter(g=>g&&typeof g.a==='string'&&typeof g.b==='string'&&typeof g.result==='string'&&Number.isInteger(g.turns)&&g.original&&typeof g.original.a==='string'&&typeof g.original.b==='string'&&g.original.a.length<=100000&&g.original.b.length<=100000&&g.original.config&&typeof g.original.config==='object').slice(0,30);
 if(Array.isArray(d.tournaments))out.tournaments=d.tournaments.filter(t=>t&&typeof t.name==='string'&&T.FORMATS.includes(t.format)&&t.settings&&Array.isArray(t.rows)&&t.rows.length<=32&&t.rows.every(r=>r&&typeof r.name==='string'&&['points','wins','draws','losses','played'].every(k=>Number.isInteger(r[k])&&r[k]>=0))&&Array.isArray(t.entries)&&t.entries.length<=32&&t.entries.every(w=>w&&typeof w.id==='string'&&typeof w.code==='string'&&w.code.length<=100000)&&Array.isArray(t.matches)&&t.matches.length<=600&&t.matches.every(m=>m&&typeof m.a==='string'&&typeof m.b==='string'&&Array.isArray(m.games)&&m.games.length<=32&&m.games.every(g=>g&&typeof g.seed==='string'&&['A','B','Empate'].includes(g.winner)&&Array.isArray(g.positions)&&g.positions.length===2&&g.positions.every(Number.isInteger)))).slice(0,10);
 return out;
}
let data=load(),route='home',lesson=0,dailySlot=0,puzzleDate=C.madridDate(),currentPuzzle=null,puzzleFeedback='',practiceCount=0,libraryFilter='',battle=null,running=false,demo=null,worker=null,tournament=null,tournamentRunning=false,tournamentSelection=new Set(),tournamentProgress=null,frameTime=0,lastDay=C.madridDate(),archiveMode=false;
let config={coreSize:800,maxCycles:20000,maxProcesses:256,maxLength:100,minDistance:100,pSpaceSize:512,seed:'',firstWarrior:'random',drawPolicy:'draw'};
data.prefs=S.sanitize(S.read('ogun_prefs',defaults.prefs));
try{const savedRules=S.read('ogun_arena',null);if(savedRules){const next={...config,...savedRules};E.validateSettings(next);if(['draw','territory','processes'].includes(next.drawPolicy))config=next;}}catch{}
const tournamentDefaults={name:'Copa del núcleo',...T.DEFAULTS,...L.DEFAULTS,coreSize:800,maxCycles:10000,maxProcesses:256,maxLength:100,minDistance:100,pSpaceSize:512,seed:''};
let tournamentDraft={...tournamentDefaults},uploads=[],uploadCounter=0;
try{const draft=S.read('ogun_tournament',null);if(draft){L.options(draft);E.validateSettings({...E.DEFAULT_SETTINGS,...draft});tournamentDraft={...tournamentDefaults,...draft};}const stored=JSON.parse(sessionStorage.getItem('ogun_uploads')||'[]');if(Array.isArray(stored))uploads=stored.filter(w=>w&&typeof w.id==='string'&&typeof w.filename==='string'&&typeof w.code==='string'&&w.code.length<=100000).slice(0,100);uploads.forEach(w=>{if(w.selected)tournamentSelection.add(w.id);});}catch{}
let liveTournament=null,liveRuntime=null,liveSavedAt='',liveRecoveryNotice='';
try{const saved=localStorage.getItem('ogun_live_v1');if(saved)liveTournament=L.restore(JSON.parse(saved));}catch{try{const previous=localStorage.getItem('ogun_live_previous_v1');if(!previous)throw new Error('Sin copia anterior');liveTournament=L.restore(JSON.parse(previous));localStorage.setItem('ogun_live_v1',JSON.stringify(liveTournament));liveRecoveryNotice='Se ha recuperado la copia anterior del torneo. La emisión está en pausa.';}catch{liveRecoveryNotice='No se pudo recuperar el torneo guardado. Puedes cargar una copia JSON desde Torneos.';}}

let resultQueue=[],resultActive=false,resultDeadline=0,resultReturnFocus=null;
const tournamentEntries=()=>[...uploads,...allWarriors()];
const formatName=f=>({swiss:'Suizo',league:'Liga',knockout:'Eliminatoria',random:'Aleatorio por jornadas',double:'Doble eliminación',groups:'Grupos y fase final'}[f]||f);
function saveSession(){const {coreSize,maxCycles,maxProcesses,maxLength,minDistance,pSpaceSize,seed,firstWarrior,drawPolicy}=config;S.write('ogun_prefs',data.prefs);S.write('ogun_arena',{coreSize,maxCycles,maxProcesses,maxLength,minDistance,pSpaceSize,seed,firstWarrior,drawPolicy});S.write('ogun_tournament',tournamentDraft);}
function saveUploads(){uploads.forEach(w=>w.selected=tournamentSelection.has(w.id));try{sessionStorage.setItem('ogun_uploads',JSON.stringify(uploads.map(({report,...w})=>w)));}catch{notice('No se pudieron conservar los archivos subidos durante la sesión.');}}
const allWarriors=()=>[...D.warriors,...data.custom];
function save(){try{saveSession();const {prefs,...progress}=data;localStorage.setItem('ogun-v1',JSON.stringify(progress));return true;}catch{storageIssue=true;notice('No se pudo guardar en este navegador. Exporta tus datos para conservarlos.');return false;}}
function notice(msg){const n=$('#notice');n.textContent=msg;n.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.classList.remove('show'),4500);}
function applyPrefs(){const p=data.prefs;document.body.dataset.theme=p.theme;document.body.dataset.reduced=p.reduced;document.body.dataset.contrast=p.contrast;document.documentElement.style.setProperty('--size',p.size+'px');document.documentElement.style.setProperty('--a',p.a);document.documentElement.style.setProperty('--b',p.b);document.body.dataset.coreShape=p.coreShape;document.body.dataset.background=p.background;document.documentElement.style.setProperty('--core-width',p.coreWidth+'px');document.documentElement.style.setProperty('--ambient-opacity',p.backgroundOpacity/100);document.documentElement.style.setProperty('--ambient-speed',p.backgroundSpeed+'s');}

function download(name,text,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function countSolved(){return Object.values(data.solved).filter(Boolean).length;}
function header(){return `<header><a href="#home" class="brand" aria-label="OGUN, inicio"><img src="icon.svg" alt=""><span>OGUN<small>CORE WAR ARENA</small></span></a><nav aria-label="Principal">${[['home','Inicio'],['arena','Jugar'],['workshop','Taller'],['puzzles','Puzles'],['learn','Aprender'],['tournaments','Torneos'],['warriors','Guerreros']].map(([r,n])=>`<a href="#${r}" ${route===r?'class="active" aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="header-end"><span class="pill"><i class="dot"></i> SIN CUENTAS · TU ARENA</span></div><a href="#settings" class="button small" aria-label="Personalización">⚙</a></header>`;}
function title(t,subtitle,extra=''){return `<div class="titlebar"><div><div class="eyebrow">OGUN / ${esc(t)}</div><h1>${esc(t)}</h1><p>${esc(subtitle)}</p></div>${extra}</div>`;}
function puzzleHTML(p,context='puzzle'){
 return `<div class="panel-head"><div><span class="eyebrow">${context==='daily'?'RETO DIARIO / '+esc(puzzleDate):context==='lesson'?'PONLO EN PRÁCTICA':'LABORATORIO DE TÁCTICAS'}</span><h2 style="margin-top:8px">${esc(p.title)}</h2></div><span class="pill">${data.solved[p.id]?'✓ RESUELTO':'REDCode'}</span></div><p>${esc(p.goal)}</p><pre class="puzzle-code" aria-label="Código del puzle">${esc(p.source).replace('??','<span class="hole">??</span>')}</pre><div class="puzzle-controls"><label>Completa ?? con un número<input id="answer" type="text" inputmode="numeric" autocomplete="off" placeholder="Tu respuesta" aria-label="Respuesta al puzle"></label><button class="primary" data-action="check-puzzle">Comprobar ↗</button><button data-action="hint-puzzle">Pista</button></div><div id="puzzle-feedback" aria-live="polite">${puzzleFeedback}</div><div class="flex between" style="margin-top:14px"><span class="micro">${p.n} CELDAS · ${p.turns} TURNO${p.turns>1?'S':''} PROPIO${p.turns>1?'S':''}</span><button class="ghost small" data-action="solution-puzzle">Ver solución</button></div>`;
}
function home(){currentPuzzle=C.daily(puzzleDate,dailySlot);return `<section class="hero reveal"><div><div class="eyebrow">EL CÓDIGO ES TU ESTRATEGIA.</div><h1>Piensa. Programa.<br><span class="accent">Conquista el núcleo.</span></h1><p>Dos guerreros. Una memoria compartida. Aprende a escribir el código que sobrevive y convierte cada instrucción en tu próxima jugada.</p><div class="hero-buttons"><a href="#arena" class="button primary">Entrar en la arena <span>↗</span></a><a href="#workshop" class="button">Crear con bloques</a><a href="#learn" class="button ghost">Aprender desde cero</a></div><div class="flex" style="margin-top:24px"><span class="pill">REDCode</span><span class="pill">EN CASTELLANO</span><span class="micro">Creado por Sara y Pascal</span></div></div><div class="hero-art"><div class="art-label"><span><i class="dot" style="display:inline-block"></i> ARENA / IMP CONTRA DWARF</span><span>MEMORIA CIRCULAR</span></div><canvas id="demo-canvas" width="640" height="240" role="img" aria-label="Animación de una batalla de Core War"></canvas><div class="art-status"><span style="color:var(--a)">◆ IMP</span><span id="demo-turns">NÚCLEO / 1.024 CELDAS</span><span style="color:var(--b)">◆ DWARF</span></div></div></section><section class="grid four"><div class="panel stat"><strong>09</strong><span>lecciones para empezar</span></div><div class="panel stat"><strong>03<span style="display:inline;font-size:.8rem"> / día</span></strong><span>retos nuevos cada medianoche</span></div><div class="panel stat"><strong>${String(countSolved()).padStart(2,'0')}</strong><span>puzles que has resuelto</span></div><div class="panel stat"><strong>${String(data.lessons.length).padStart(2,'0')}<span style="display:inline;font-size:.8rem"> / 9</span></strong><span>lecciones completadas</span></div></section><section class="home-grid section"><article class="panel">${puzzleHTML(currentPuzzle,'daily')}</article><aside class="panel"><div class="panel-head"><h2>Tu siguiente movimiento</h2><span class="micro">APRENDE → JUEGA</span></div>${[['learn','01','Comprende el núcleo','Un recorrido guiado con ejercicios.'],['warriors','02','Elige tu guerrero','Explora bombas, copias y escáneres.'],['tournaments','03','Ponlo a prueba','Una liga, varios rivales, todas las rondas.']].map(([r,n,t,d])=>`<a class="list-row" href="#${r}"><div class="icon-box">${n}</div><div><strong>${t}</strong><span>${d}</span></div><span class="arrow">↗</span></a>`).join('')}<div class="note" style="font-size:.8rem;margin-bottom:0">Tu progreso se conserva en este navegador. Puedes exportarlo y llevarlo contigo desde Personalización.</div></aside></section><section class="grid three section">${[['arena','01 / ARENA','Cada turno cuenta.','Escribe, carga y observa tus guerreros. Pausa la batalla para inspeccionar cualquier celda.','Crear una partida'],['puzzles','02 / ENTRENAMIENTO','Un reto. Cada día.','Resuelve tres desafíos diarios o entrena sin fin con nuevos ejercicios generados al instante.','Resolver puzles'],['tournaments','03 / COMPETICIÓN','Que gane el mejor código.','Organiza ligas o eliminatorias y compara estrategias con rondas y posiciones reproducibles.','Crear un torneo']].map(([r,n,t,d,b])=>`<a href="#${r}" class="panel feature"><span class="num">${n}</span><h3>${t}</h3><p>${d}</p><span class="arrow">${b} ↗</span></a>`).join('')}</section>`;}
function arena(){return title('Arena','Escribe tu estrategia. Mira cómo cobra vida.',`<div class="flex"><button data-action="share-battle" class="small">Compartir partida ↗</button><button data-action="export-battle" class="small">Exportar</button><button data-action="import-battle" class="small">Importar</button></div>`)+`<div class="arena-grid"><section><div class="panel arena-core"><div class="panel-head"><h2>Núcleo compartido</h2><div class="flex"><span class="warrior-tag">◆ A</span><span class="warrior-tag b">◆ B</span><span class="micro" id="core-size">${config.coreSize} CELDAS</span></div></div><div class="canvas-wrap"><canvas id="core-canvas" width="960" height="350" role="img" aria-label="Memoria compartida de la batalla. Usa el inspector numérico para leer una celda."></canvas></div><div class="arena-stats"><div><strong id="turn-count">0</strong><span>Turnos / ${config.maxCycles}</span></div><div><strong id="process-a">1</strong><span>Procesos A</span></div><div><strong id="process-b">1</strong><span>Procesos B</span></div></div><div class="meter"><span id="battle-meter" style="width:0%"></span></div><div class="controls"><button class="primary" data-action="run-battle" id="run-btn">▶ Iniciar batalla</button><button data-action="step-battle">Un turno</button><button data-action="batch-battle">+100 turnos</button><button data-action="new-battle">Nueva posición</button><button data-action="replay-battle">↺ Repetir</button><button data-action="refresh-core">Actualizar núcleo</button><select id="speed" style="width:auto" aria-label="Velocidad">${[[20,'Lenta'],[200,'Normal'],[2000,'Rápida'],[10000,'Turbo']].map(([v,n])=>`<option value="${v}" ${data.prefs.speed===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="inspector"><label class="flex">Inspeccionar celda<input id="inspect-index" type="number" min="0" max="${config.coreSize-1}" value="0" style="width:100px"></label><div id="inspect-text" style="margin-top:8px">Carga una batalla para inspeccionar la memoria.</div></div></div><div class="editor-grid section">${['a','b'].map((id,i)=>`<article class="panel editor"><div class="editor-header"><span class="warrior-tag ${id==='b'?'b':''}">◆ GUERRERO ${id.toUpperCase()}</span><div class="editor-tools"><select id="select-${id}" aria-label="Cargar guerrero ${id.toUpperCase()}"><option value="">Cargar guerrero…</option>${allWarriors().map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('')}</select></div></div><label class="sr" for="code-${id}">Código Redcode del guerrero ${id.toUpperCase()}</label><textarea id="code-${id}" spellcheck="false">${esc(data.draft[id])}</textarea><div class="controls"><button class="small" data-action="validate-code" data-side="${id}">Validar</button><button class="small" data-action="save-warrior" data-side="${id}">Guardar</button><button class="small" data-action="import-warrior" data-side="${id}">Abrir .red</button><button class="small" data-action="export-warrior" data-side="${id}">Descargar</button></div><div id="validation-${id}" class="micro" aria-live="polite" style="margin-top:10px">Modifica el código antes de iniciar la partida.</div></article>`).join('')}</div>${W.panelHTML()}</section><aside class="arena-side"><div class="panel"><h2>Estado de la partida</h2><div id="battle-result" class="result" role="status">Listo para cargar los guerreros.</div><h3>Reglas de la arena</h3><div class="config-fields">${[['coreSize','Celdas',32,32768],['maxCycles','Límite de turnos',1,500000],['maxProcesses','Procesos / guerrero',1,8000],['minDistance','Distancia mínima',0,32768],['maxLength','Longitud máxima',1,1000]].map(([k,n,min,max])=>`<label>${n}<input id="cfg-${k}" type="number" min="${min}" max="${max}" value="${config[k]}"></label>`).join('')}<label>Quién empieza<select id="cfg-firstWarrior">${[['random','Sorteo'],['A','Guerrero A'],['B','Guerrero B']].map(([v,n])=>`<option value="${v}" ${config.firstWarrior===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="full">Al llegar al límite<select id="cfg-drawPolicy">${[['draw','Mantener empate'],['territory','Más celdas escritas'],['processes','Más procesos vivos']].map(([v,n])=>`<option value="${v}" ${config.drawPolicy===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="full">Semilla <span class="micro">(vacía = sorteo nuevo)</span><input id="cfg-seed" value="${esc(config.seed)}" maxlength="256" placeholder="Ej. mi-duelo-01"></label></div><p class="micro" style="margin:16px 0 0">La memoria es circular. La victoria depende de los procesos vivos. Al límite se aplica tu regla de empate. Un turno ejecuta una instrucción de un guerrero.</p><div id="load-info" class="micro" style="margin-top:12px"></div></div><div class="panel section"><h2>Últimos movimientos</h2><div id="trace" class="trace">La batalla todavía no ha empezado.</div></div><div class="panel section"><h2>Tus últimas partidas</h2><div id="history-list">${historyHTML()}</div></div></aside></div>`;}
function historyHTML(){return data.history.length?data.history.slice(0,5).map((g,i)=>`<div class="list-row"><div><strong>${esc(g.a)} · ${esc(g.b)}</strong><span>${esc(g.result)} · ${Number(g.turns)||0} turnos</span></div><button class="small" data-action="history-replay" data-index="${i}">Repetir</button></div>`).join(''):'<p class="micro">Aquí aparecerán tus partidas terminadas.</p>';}
function puzzles(){if(!currentPuzzle||!currentPuzzle.id.startsWith(archiveMode?'practice:':'ogun-v1:'))currentPuzzle=C.daily(puzzleDate,dailySlot);return title('Puzles','Entrena tu lectura del código. Un pequeño reto, una nueva idea.',`<span class="pill">${countSolved()} RESUELTOS</span>`)+`<div class="grid two"><section><div class="tabs">${['Iniciación','Táctica','Multiproceso'].map((n,i)=>`<button data-action="daily-slot" data-slot="${i}" class="${!archiveMode&&dailySlot===i?'active':''}">${n}</button>`).join('')}<button data-action="new-puzzle" class="${archiveMode?'active':''}">∞ Entrenamiento</button></div><article class="panel reveal">${puzzleHTML(currentPuzzle,archiveMode?'puzzle':'daily')}</article>${archiveMode?'<button class="primary section" data-action="new-puzzle">Siguiente reto ↗</button>':''}</section><aside><div class="panel"><h2>Tres retos nuevos cada día</h2><p>Los desafíos se generan automáticamente para cada fecha. Todas las personas reciben el mismo reto diario. Cada respuesta se verifica ejecutando el código.</p><label>Archivo de retos diarios<input id="puzzle-date" type="date" value="${esc(puzzleDate)}" max="${C.madridDate()}"></label><div class="list-row"><div class="icon-box">↻</div><div><strong>Se renuevan a medianoche</strong><span>Hora de Madrid · próximo reto en <span id="countdown">—</span></span></div></div><div class="list-row"><div class="icon-box">∞</div><div><strong>Entrena a tu ritmo</strong><span>Más ejercicios, sin esperar al día siguiente.</span></div></div></div><div class="panel section"><h2>Cómo resolver un puzle</h2><p>Lee el objetivo, sigue los turnos y sustituye <span class="mono">??</span> por un número. Puedes pedir una pista. Si te atascas, mira la solución y vuelve a intentarlo.</p><a href="#learn" class="button small">Aprender Redcode ↗</a></div></aside></div>`;}
function learn(){const l=D.lessons[lesson];currentPuzzle=C.puzzle(`lesson:${lesson}`,l.kind);return title('Aprender Core War','De tu primera instrucción a tu primer torneo.',`<span class="pill">${data.lessons.length} / 9 COMPLETADAS</span>`)+`<div class="learn-layout"><aside class="panel lesson-menu" aria-label="Lecciones">${D.lessons.map((l,i)=>`<button data-action="lesson" data-index="${i}" class="${lesson===i?'active':''}"><span class="mono">${data.lessons.includes(i)?'✓':String(i+1).padStart(2,'0')}</span> ${esc(l.title)}</button>`).join('')}</aside><article class="panel lesson-content reveal"><span class="tag">${esc(l.tag)}</span><h2>${esc(l.title)}</h2><p>${esc(l.text)}</p><div class="note">${esc(l.extra)}</div><div class="section">${puzzleHTML(currentPuzzle,'lesson')}</div><div class="flex between section"><button data-action="lesson-prev" ${lesson===0?'disabled':''}>← Anterior</button><button data-action="lesson-complete" class="primary">${data.lessons.includes(lesson)?'✓ Completada':'Marcar como leída'}</button><button data-action="lesson-next" ${lesson===8?'disabled':''}>Siguiente →</button></div></article></div><details class="panel section"><summary>Referencia rápida de Redcode</summary><div class="table-wrap section"><table><thead><tr><th>Elemento</th><th>Significado</th><th>Ejemplo</th></tr></thead><tbody>${[['MOV.I','Copia la instrucción completa','MOV.I 0, 1'],['DAT','Termina el proceso que lo ejecuta','DAT #0, #0'],['ADD / SUB / MUL','Suma / resta / multiplica campos','ADD.AB #4, ptr'],['DIV / MOD','Divide / calcula resto; cero termina el proceso','DIV.AB #2, ptr'],['JMP','Salto incondicional','JMP -2'],['JMZ / JMN','Salto si el destino es cero / distinto de cero','JMZ inicio, ptr'],['DJN','Decrementa y salta si queda distinto de cero','DJN inicio, ptr'],['SEQ / SNE / SLT','Compara y omite la siguiente instrucción','SEQ.I 2, 3'],['SPL / NOP','Abre una rama / continúa','SPL 2'],['LDP / STP','Lee / guarda en P-space','STP.AB #5, #1'],['# / $','Inmediato / directo','MOV.AB #7, $3'],['@ / *','Indirecto B / indirecto A','MOV.I 2, @3'],['< / {','Predecremento B / A','MOV.I 2, <3'],['> / }','Postincremento B / A','MOV.I 2, >3'],['.A / .B / .AB / .BA','Campos de origen y destino','MOV.AB #5, 3'],['.F / .X / .I','Ambos campos / cruzados / instrucción','MOV.X 2, 3'],['EQU / ORG / END','Constante / entrada / fin','paso EQU 4'],['FOR / ROF','Repetición al ensamblar','FOR 3 … ROF']].map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
function warriors(){const list=allWarriors().filter(w=>`${w.name} ${w.type} ${w.level}`.toLowerCase().includes(libraryFilter.toLowerCase()));return title('Guerreros','Una biblioteca de estrategias para explorar, modificar y competir.',`<button class="primary" data-action="new-warrior">+ Crear guerrero</button>`)+`<label style="max-width:450px;margin-bottom:22px">Buscar por nombre o estrategia<input id="warrior-search" value="${esc(libraryFilter)}" placeholder="Imp, bombardero, personal…"></label><div class="grid three" id="warrior-grid">${list.length?list.map(w=>`<article class="panel library-card reveal"><div class="flex between"><span class="pill">${esc(w.type)}</span><span class="micro">${esc(w.level)}</span></div><h2 style="margin:18px 0 8px">${esc(w.name)}</h2><p>${esc(w.description)}</p><details><summary class="micro">Ver código</summary><pre>${esc(w.code)}</pre></details><div class="actions section"><button class="small primary" data-action="load-warrior" data-id="${esc(w.id)}" data-side="a">Jugar como A ↗</button><button class="small" data-action="load-warrior" data-id="${esc(w.id)}" data-side="b">Como B</button>${w.type==='Personal'?`<button class="small" data-action="delete-warrior" data-id="${esc(w.id)}" aria-label="Eliminar ${esc(w.name)}">×</button>`:''}</div></article>`).join(''):'<div class="panel empty">No hay guerreros con esa búsqueda.</div>'}</div>`;}
function liveName(id){const e=liveTournament?.entries.find(e=>e.id===id);return e?(e.owner?e.owner+' · '+e.name:e.name):'BYE';}
function liveSave(){if(!liveTournament)return false;try{const text=JSON.stringify(liveTournament),old=localStorage.getItem('ogun_live_v1');if(old&&old!==text){try{localStorage.setItem('ogun_live_previous_v1',old);}catch{localStorage.removeItem('ogun_live_previous_v1');}}try{localStorage.setItem('ogun_live_v1',text);}catch{localStorage.removeItem('ogun_live_previous_v1');localStorage.setItem('ogun_live_v1',text);}liveSavedAt=new Date().toLocaleTimeString('es');return true;}catch{notice('No se ha podido guardar este estado. Usa Guardar torneo para descargar una copia.');return false;}}
function loadLive(previous=false){const raw=localStorage.getItem(previous?'ogun_live_previous_v1':'ogun_live_v1');if(!raw)throw new Error('No hay una copia guardada.');const next=L.restore(JSON.parse(raw));liveRuntime=null;liveTournament=next;tournamentProgress=null;tournament=null;if(previous)liveSave();render();notice('Torneo recuperado en pausa. Las partidas terminadas se han conservado.');}
function slotHTML(m,id,ref,side){const e=liveTournament.entries.find(e=>e.id===id),won=terminalLive(m)&&m.winnerId===id&&id;let text=e?(e.owner||e.name):m.status==='bye'||ref?.kind==='entry'?'BYE':`${ref?.kind==='loser'?'Perdedor':'Ganador'} ${ref?.id||''}`;const score=m.result?(side==='a'?m.result.aWins:m.result.bWins):'—';return `<div class="bracket-slot ${won?'slot-winner':''} ${!id?'slot-pending':''}"><span class="bracket-avatar">${e?esc((e.owner||e.name).slice(0,2).toUpperCase()):'–'}</span><span class="bracket-name" title="${esc(e?liveName(id):text)}">${esc(text)}${e?.owner?`<small>${esc(e.name)}</small>`:''}</span><strong>${m.status==='bye'&&id?'BYE':score}</strong></div>`;}
function terminalLive(m){return['complete','bye'].includes(m.status);}
function bracketHTML(list,titleText){if(!list.length)return'';const rounds=[...new Set(list.map(m=>m.round))].sort((a,b)=>a-b),counts=rounds.map(r=>list.filter(m=>m.round===r).length),height=Math.max(230,Math.max(...counts)*112),width=rounds.length*274-32,positions=new Map();
 for(let c=0;c<rounds.length;c++){const level=list.filter(m=>m.round===rounds[c]);level.forEach((m,i)=>positions.set(m.id,{x:c*274,y:(i+.5)*height/level.length-42}));}
 let lines='';for(const m of list){const p=positions.get(m.id);for(const ref of [m.aRef,m.bRef]){const from=positions.get(ref?.id);if(from){const x1=from.x+242,y1=from.y+42,x2=p.x,y2=p.y+42;lines+=`<path class="${ref.kind==='loser'?'connector-loss':''}" d="M ${x1} ${y1} H ${x1+16} V ${y2} H ${x2}"/>`;}}}
 const roundTitle=(r,c)=>{const size=counts[c]*2;if(titleText.startsWith('Grupo'))return r===1?'Apertura':r===2?'Ganadores / recuperación':'Segundo clasificado';if(titleText==='Gran final')return r===1?'Gran final':'Final definitiva';return size===2?'Final':size===4?'Semifinales':size===8?'Cuartos':size===16?'Octavos':'Ronda '+r;};
 return `<section class="bracket-section"><h3>${esc(titleText)}</h3><div class="bracket-scroll" tabindex="0" aria-label="Cuadro de ${esc(titleText)}"><div class="bracket-headings" style="width:${width}px">${rounds.map((r,c)=>`<span style="left:${c*274}px">${roundTitle(r,c)}</span>`).join('')}</div><div class="bracket-body" style="width:${width}px;height:${height}px"><svg class="bracket-connectors" viewBox="0 0 ${width} ${height}" aria-hidden="true">${lines}</svg>${list.map(m=>{const p=positions.get(m.id),active=liveRuntime?.matchId===m.id&&!['paused','done'].includes(liveRuntime?.phase);return `<article class="bracket-card ${m.status} ${active?'on-air':''}" style="left:${p.x}px;top:${p.y}px" aria-label="${m.status==='waiting'?esc(m.id)+', pendiente de clasificar':esc(m.id)+': '+esc(liveName(m.aId))+' contra '+esc(liveName(m.bId))}"><div class="bracket-meta"><span>${esc(m.id)}</span><span>${m.status==='bye'?'PASE AUTOMÁTICO':active?'EN DIRECTO':m.status==='complete'?(m.result?.manual?'CORREGIDO':'FINALIZADO'):m.status==='ready'?'LISTO':'PENDIENTE'}</span></div>${slotHTML(m,m.aId,m.aRef,'a')}${slotHTML(m,m.bId,m.bRef,'b')}${m.status==='ready'?`<button class="bracket-play" data-action="live-match" data-id="${m.id}" aria-label="Empezar duelo ${m.id}">▶</button>`:''}</article>`;}).join('')}</div></div></section>`;
}
function liveStandings(v){return `<div class="panel-head"><h2>Clasificación</h2><span class="pill">${v.complete?'FINAL':v.phase==='playoff'?'FASE PREVIA + CUADRO FINAL':'EN CURSO'}</span></div><div class="podium-list">${v.rows.slice(0,3).map((r,i)=>`<div class="podium-item"><b>${i+1}</b><span>${esc(r.name)}<small>${esc(r.warrior)}</small></span><strong>${r.points}<small>PTS</small></strong></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>#</th><th>Participante / guerrero</th><th>Pts</th><th>V / E / D</th><th>Buchholz</th><th>BYE</th><th>Estado</th></tr></thead><tbody>${v.rows.map((r,i)=>`<tr><td>${i+1}</td><td><strong>${esc(r.name)}</strong><span class="micro">${esc(r.warrior)}</span></td><td>${r.points}</td><td>${r.wins} / ${r.draws} / ${r.losses}</td><td>${r.buchholz}</td><td>${r.byes}</td><td>${r.id===v.champion?'♜ Campeón':r.eliminated?'Eliminado':v.qualifiers.includes(r.id)?'Clasificado':'En competición'}</td></tr>`).join('')}</tbody></table></div><p class="micro section">${liveTournament.options.winPoints} puntos por duelo ganado · ${liveTournament.options.drawPoints} por empate · ${liveTournament.options.byePoints} por descanso de liguilla. En eliminatoria, BYE significa pase directo. En la fase final se conserva la clasificación de la fase previa.</p>`;}
function liveHistory(v){return `<h2>Historial de duelos</h2>${v.matches.filter(terminalLive).length?v.matches.filter(terminalLive).map(m=>`<details class="match-card"><summary><span class="micro">${esc(m.id)}</span> · ${esc(liveName(m.aId))}${m.bId?' contra '+esc(liveName(m.bId)):''} · <strong>${m.status==='bye'?'BYE':m.result.aWins+' – '+m.result.bWins}</strong>${m.result?.manual?' · Corrección del organizador':''}</summary>${m.result?`<p>${m.result.draws} empates · ${m.result.tiebreak?'Avanza '+esc(liveName(m.winnerId))+' tras desempate.':''}${m.result.manual?' Motivo: '+esc(m.result.reason):''}</p>${m.result.games.map((g,i)=>`<div class="flex between"><span class="micro">Partida ${i+1} · ${esc(g.winner==='Empate'?'Empate':liveName(g.winner==='A'?m.aId:m.bId))} · ${g.turns} turnos</span><button class="small" data-action="live-replay" data-id="${m.id}" data-game="${i}">Reproducir ↗</button></div>`).join('')}`:'<p>Pase automático sin jugar ni consumir una partida.</p>'}</details>`).join(''):'<p class="micro">Los resultados aparecerán aquí al terminar cada duelo.</p>'}<details class="section"><summary>Registro del organizador (${liveTournament.audit.length})</summary><div class="audit-log">${liveTournament.audit.slice(-100).reverse().map(e=>`<div><span class="micro">${esc(e.at)}${e.matchId?' · '+esc(e.matchId):''}</span><p>${esc(e.text)}${e.undone?' (deshecho)':''}${Object.keys(e.discarded||{}).length?' · Cruces recalculados: '+Object.keys(e.discarded).length:''}</p></div>`).join('')}</div></details>`;}
function organizerHTML(v){const editable=v.matches.filter(m=>m.aId&&m.bId&&['ready','complete'].includes(m.status));return `<details class="panel section organizer-panel"><summary>Control del organizador · corregir, guardar y recuperar</summary><p class="micro section">Pausa la emisión antes de intervenir. Corregir un resultado recalcula los cruces dependientes; los duelos cuyo emparejamiento cambie vuelven a quedar pendientes. Cada cambio conserva su motivo.</p><div class="grid three"><div><h3>Corregir un duelo</h3><label>Duelo${selectHTML('live-edit-match',editable.map(m=>[m.id,m.id+' · '+liveName(m.aId)+' / '+liveName(m.bId)]),editable[0]?.id)}</label><div class="config-fields section"><label>Victorias A<input id="live-edit-a" type="number" min="0" max="1000" value="1"></label><label>Victorias B<input id="live-edit-b" type="number" min="0" max="1000" value="0"></label><label>Empates<input id="live-edit-draw" type="number" min="0" max="1000" value="0"></label><label>Si empatan y debe pasar alguien${selectHTML('live-edit-winner',[['','Elegir…'],['A','Participante A'],['B','Participante B']],'')}</label></div><label class="section">Motivo<input id="live-edit-reason" maxlength="500" placeholder="Explica la incidencia"></label><button class="section" data-action="live-correct">Aplicar corrección</button></div><div><h3>Participantes y puntos</h3><label>Participante${selectHTML('live-edit-person',liveTournament.entries.map(e=>[e.id,liveName(e.id)]),liveTournament.entries[0]?.id)}</label><label class="section">Nombre de la persona<input id="live-edit-owner" maxlength="80" placeholder="Nombre o equipo"></label><button class="section" data-action="live-rename">Actualizar nombre</button><label class="section">Ajuste de puntos (+ / −)<input id="live-edit-points" type="number" min="-1000" max="1000" value="0"></label><label>Motivo<input id="live-points-reason" maxlength="500" placeholder="Explica el ajuste"></label><button class="section" data-action="live-points">Aplicar ajuste</button></div><div><h3>Recuperación</h3><div class="controls"><button class="primary" data-action="live-save">Guardar torneo JSON</button><button data-action="live-import">Cargar torneo JSON</button><button data-action="live-undo">Deshacer último cambio</button><button data-action="live-backup">Restaurar copia anterior</button></div><div class="note micro">Guardado automático después de cada partida y resultado. Al recuperar, el torneo queda en pausa; una partida interrumpida se vuelve a ejecutar con la misma semilla. Las partidas ya terminadas se conservan.</div></div></div></details>`;}
function liveHTML(){const v=L.view(liveTournament),current=v.matches.find(m=>m.id===liveRuntime?.matchId)||v.next,paused=!liveRuntime||liveRuntime.phase==='paused',playing=liveRuntime&&['countdown','running','intermission'].includes(liveRuntime.phase),o=liveTournament.options;
 const phases=[['upper','Cuadro de ganadores'],['lower','Cuadro de recuperación'],['final','Gran final'],...v.groups.map(g=>['group-'+g.number,'Grupo '+g.number]),['playoff','Fase final']];
 return `<div id="live-shell" class="live-shell" data-stage-effect="${data.prefs.reduced?'off':o.stageStyle}" style="--stage-color:${o.stageColor}"><div class="broadcast-heading"><div><span class="eyebrow">OGUN / TORNEO EN DIRECTO</span><h2>${esc(liveTournament.name)}</h2><span class="micro">${esc(formatName(o.format))} · ${liveTournament.entries.length} participantes · ${v.matches.filter(terminalLive).length} / ${v.matches.length} cruces resueltos</span></div><div class="flex"><button data-action="live-fullscreen">Modo proyector ⛶</button><button data-action="live-save">Guardar</button><button data-action="live-import">Cargar</button></div></div><div class="live-toolbar"><button class="primary" data-action="live-play" ${v.complete||playing?'disabled':''}>${liveRuntime?.phase==='paused'?'▶ Reanudar':'▶ Comenzar espectáculo'}</button><button data-action="live-pause" ${!playing?'disabled':''}>Ⅱ Pausar</button><button data-action="live-next" ${v.complete||playing?'disabled':''}>Siguiente duelo ↗</button><label class="inline"><input id="live-auto" type="checkbox" ${o.autoAdvance?'checked':''}> Avanzar automáticamente</label><label>Velocidad${selectHTML('live-speed',[[20,'Lenta'],[200,'Normal'],[2000,'Rápida'],[10000,'Turbo']],o.liveSpeed)}</label><span class="micro" id="live-save-status">${liveSavedAt?'Guardado '+esc(liveSavedAt):'Torneo preparado y guardado'}</span></div><div class="panel stage-panel"><div class="stage-aura" aria-hidden="true"></div><div class="stage-versus"><div><span class="warrior-tag">PARTICIPANTE A</span><h3 id="stage-a">${esc(current?liveName(current.aId):v.champion?liveName(v.champion):'Esperando')}</h3></div><span class="versus-mark">VS</span><div><span class="warrior-tag b">PARTICIPANTE B</span><h3 id="stage-b">${esc(current?liveName(current.bId):'—')}</h3></div></div><div class="stage-memory"><canvas id="stage-core" width="720" height="720" role="img" aria-label="Memoria del duelo en directo"></canvas><div id="stage-countdown" class="stage-countdown ${liveRuntime?.phase==='countdown'&&o.countdown>0?'':'hidden'}" aria-live="assertive">${Math.max(1,Math.ceil(((liveRuntime?.until||Date.now())-Date.now())/1000))}</div></div><div class="stage-bottom"><strong id="stage-status" role="status" aria-live="polite">${v.complete?v.champion?'♜ Campeón: '+esc(liveName(v.champion)):'Competición terminada':playing?'Emisión en curso':paused?'Preparado · emisión en pausa':'Preparado'}</strong><span id="stage-metrics" class="mono micro">${current?esc(current.id):''}</span></div></div>${v.complete?`<div class="champion-banner"><span>♜</span><div><div class="eyebrow">${v.champion?'CAMPEÓN':'CLASIFICACIÓN FINAL'}</div><h2>${esc(v.champion?liveName(v.champion):v.leaders.map(liveName).join(' · '))}</h2></div></div>`:''}<div class="panel section"><div class="panel-head"><h2>Cuadro de la competición</h2><span class="pill">${v.phase==='playoff'?'FASE FINAL':v.complete?'FINALIZADO':'SE ACTUALIZA AUTOMÁTICAMENTE'}</span></div>${phases.map(([phase,title])=>bracketHTML(v.matches.filter(m=>m.phase===phase),title)).join('')}${v.matches.some(m=>['league','swiss','random'].includes(m.phase))?`<div class="fixtures-grid">${[...new Set(v.matches.filter(m=>['league','swiss','random'].includes(m.phase)).map(m=>m.round))].map(r=>`<div class="fixture-round"><h3>Jornada ${r}</h3>${v.matches.filter(m=>m.round===r&&['league','swiss','random'].includes(m.phase)).map(m=>`<div class="fixture-card ${m.status}"><span class="micro">${esc(m.id)} · ${m.status==='bye'?'BYE':m.status==='complete'?'FINALIZADO':m.status==='ready'?'LISTO':'PENDIENTE'}</span><strong>${esc(liveName(m.aId))}</strong><span>${m.status==='bye'?'Pasa sin jugar':esc(liveName(m.bId))}</span>${m.result?`<b>${m.result.aWins} – ${m.result.bWins} · ${m.result.draws} empates</b>`:''}${m.status==='ready'?`<button class="small" data-action="live-match" data-id="${m.id}">Empezar duelo ▶</button>`:''}</div>`).join('')}</div>`).join('')}</div>`:''}${!v.complete&&!v.matches.some(m=>m.phase==='playoff')&&['league','swiss','random','groups'].includes(o.format)&&o.qualifyCount?`<div class="note">La fase final se generará automáticamente al terminar la clasificación. Si persiste un empate en el corte tras aplicar el desempate elegido, se decide con un sorteo reproducible. Pasan hasta ${o.format==='groups'?'dos participantes por grupo':o.qualifyCount+' participantes'}.</div>`:''}</div><div class="panel section">${liveStandings(v)}</div><div class="panel section">${liveHistory(v)}</div>${organizerHTML(v)}</div>`;
}
function prepareLive(){if(tournamentRunning||liveRuntime&&['countdown','running','intermission'].includes(liveRuntime.phase))throw new Error('Pausa el torneo en curso antes de preparar otro.');readTournamentDraft();clampJornadas();const reports=validateParticipants(),entries=reports.rows.filter(w=>w.report.ok&&tournamentSelection.has(w.id)).map(({report,...w})=>w);const seed=tournamentDraft.seed||String(crypto.getRandomValues(new Uint32Array(1))[0]);const next=L.create(entries,ruleSettings(),tournamentDraft,seed,tournamentDraft.name);if(liveTournament&&!L.view(liveTournament).complete&&!confirm('¿Preparar un torneo nuevo? El actual quedará en la copia anterior.'))return;liveTournament=next;liveRuntime=null;tournament=null;tournamentProgress=null;liveSave();saveSession();render();notice('Cuadro preparado. Los BYE se resuelven automáticamente.');}
function startLive(id=null){if(!liveTournament)throw new Error('Primero prepara el cuadro.');if(liveRuntime&&['countdown','running','intermission'].includes(liveRuntime.phase))throw new Error('Pausa el duelo en curso antes de empezar otro.');const v=L.view(liveTournament);if(v.complete)return;
 if(!id&&liveRuntime?.phase==='paused'){liveRuntime.phase=liveRuntime.resumePhase||'countdown';liveRuntime.until=Date.now()+(liveRuntime.remaining??liveTournament.options.countdown*1000);renderLive();return;}
 const m=id?v.matches.find(m=>m.id===id):v.matches.find(m=>m.id===liveTournament.checkpoint?.matchId)||v.next;if(!m||m.status!=='ready')throw new Error('Ese duelo aún no está disponible.');const saved=liveTournament.checkpoint?.matchId===m.id?liveTournament.checkpoint:null;
 liveRuntime={matchId:m.id,games:saved?structuredClone(saved.games):[],battle:null,phase:'countdown',until:Date.now()+liveTournament.options.countdown*1000,remaining:0,revision:liveTournament.revision,selected:!!id};checkpointLive();renderLive();}
function checkpointLive(){if(!liveTournament)return;if(liveRuntime&&liveRuntime.phase!=='done'){const m=L.view(liveTournament).matches.find(m=>m.id===liveRuntime.matchId);if(m?.status==='ready')liveTournament.checkpoint={matchId:m.id,aId:m.aId,bId:m.bId,games:structuredClone(liveRuntime.games)};}liveSave();}
function pauseLive(){if(!liveRuntime)return;liveRuntime.remaining=Math.max(0,liveRuntime.until-Date.now());liveRuntime.resumePhase=liveRuntime.phase;liveRuntime.phase='paused';checkpointLive();renderLive();}
function renderLive(){if(route!=='tournaments')return;const target=$('#tournament-results');if(target&&liveTournament){target.innerHTML=liveHTML();drawCore($('#stage-core'),liveRuntime?.battle||liveRuntime?.lastBattle||null);}if($('#live-save-status'))$('#live-save-status').textContent='Guardado '+liveSavedAt;}
function recordLiveGame(){const b=liveRuntime.battle;if(liveTournament.options.liveAnnouncements==='games'){const m=L.view(liveTournament).matches.find(m=>m.id===liveRuntime.matchId);showResult({winner:b.winner,a:liveName(m.aId),b:liveName(m.bId),reason:b.winReason},'tournament');}liveRuntime.games.push({winner:b.winner,reason:b.winReason,seed:b.settings.seed,firstWarrior:b.originalFirst,positions:b.warriors.map(w=>w.start),turns:b.cycle});liveRuntime.lastBattle=b;liveRuntime.battle=null;checkpointLive();}
function tickLive(now){if(!liveTournament||!liveRuntime||liveRuntime.phase==='paused'||document.hidden)return;if(resultActive&&liveTournament.options.liveAnnouncements==='games')return;const o=liveTournament.options;
 if(liveRuntime.phase==='intermission'){if(now<liveRuntime.until||resultActive)return;const v=L.view(liveTournament);if(v.complete){liveRuntime.phase='done';return;}if(!o.autoAdvance){liveRuntime=null;renderLive();return;}liveRuntime=null;startLive();return;}
 if(liveRuntime.phase==='countdown'){const left=liveRuntime.until-now;if(left>0){if($('#stage-countdown')){$('#stage-countdown').classList.remove('hidden');const value=String(Math.ceil(left/1000));if($('#stage-countdown').textContent!==value){$('#stage-countdown').textContent=value;$('#stage-countdown').dataset.beat=value;}}return;}liveRuntime.phase='running';$('#stage-countdown')?.classList.add('hidden');}
 if(liveRuntime.phase!=='running')return;const v=L.view(liveTournament),m=v.matches.find(m=>m.id===liveRuntime.matchId);if(!m||m.status!=='ready'||liveRuntime.revision!==liveTournament.revision){liveRuntime=null;renderLive();notice('El cuadro ha cambiado. Elige el siguiente duelo disponible.');return;}
 if(!liveRuntime.battle){if(!L.needsGame(liveTournament,m,liveRuntime.games)){finishLiveMatch(m);return;}const settings=L.gameSettings(liveTournament,m,liveRuntime.games.length),a=liveTournament.entries.find(e=>e.id===m.aId),b=liveTournament.entries.find(e=>e.id===m.bId);liveRuntime.battle=E.createBattle(E.compileWarrior(a.code,settings),E.compileWarrior(b.code,settings),settings);liveRuntime.battle.originalFirst=settings.firstWarrior;}
 const b=liveRuntime.battle;E.runSteps(b,o.liveSpeed);if(route==='tournaments'){if(data.prefs.coreMotion||b.halted)drawCore($('#stage-core'),b);if($('#stage-status')){const label=`Partida ${liveRuntime.games.length+1} · ${b.halted?'Terminada':'En combate'}`;if($('#stage-status').textContent!==label)$('#stage-status').textContent=label;}if($('#stage-metrics'))$('#stage-metrics').textContent=`${m.id} · Turno ${b.cycle} / ${b.settings.maxCycles} · Procesos A ${b.queues.A.length} / B ${b.queues.B.length}`;}
 if(b.halted)recordLiveGame();}
function finishLiveMatch(m){const r=L.tally(liveRuntime.games),a=liveName(m.aId),b=liveName(m.bId);liveTournament=L.commit(liveTournament,m.id,r);const result=liveTournament.results[m.id],v=L.view(liveTournament);liveRuntime={matchId:m.id,games:[],battle:null,lastBattle:liveRuntime.lastBattle,phase:'intermission',until:Date.now()+liveTournament.options.intermission,revision:liveTournament.revision};liveSave();renderLive();if(liveTournament.options.liveAnnouncements==='duels')showResult({winner:result.outcome,a,b,reason:result.tiebreak?'Avanza '+liveName(result.winnerId)+' tras desempate.':`${result.aWins} – ${result.bWins} · ${result.draws} empates`},'tournament');if(v.complete){liveRuntime.phase='done';if(liveTournament.options.liveAnnouncements!=='off')showResult({winner:v.champion?'A':'Empate',name:v.champion?liveName(v.champion):v.leaders.map(liveName).join(' · '),label:v.champion?'CAMPEÓN DEL TORNEO':'CLASIFICACIÓN FINAL',reason:liveTournament.name},'tournament');}}
function assertLivePaused(){if(liveRuntime&&['countdown','running','intermission'].includes(liveRuntime.phase))throw new Error('Pausa la emisión antes de modificar el torneo.');}
function applyLive(next){const event=next.audit.at(-1),discarded=Object.keys(event?.discarded||{}).length;if(discarded&&!confirm(`Este cambio deja ${discarded} cruces posteriores pendientes de nuevo. ¿Aplicarlo?`))return;liveRuntime=null;liveTournament=next;liveSave();renderLive();notice(discarded?`${discarded} cruces recalculados. Cambio guardado.`:'Cambio guardado en el historial.');}
async function liveAction(name,el){switch(name){
 case 'prepare-live':prepareLive();break;
 case 'live-play':startLive();break;
 case 'live-next':startLive();break;
 case 'live-match':startLive(el.dataset.id);break;
 case 'live-pause':pauseLive();break;
 case 'live-save':checkpointLive();if(liveTournament)download('ogun-torneo-en-directo.json',JSON.stringify(liveTournament,null,2),'application/json');else throw new Error('No hay un torneo preparado.');break;
 case 'live-import':assertLivePaused();pickFile('.json',text=>{const next=L.restore(JSON.parse(text));if(liveTournament&&!confirm('¿Reemplazar el torneo abierto por esta copia?'))return;liveRuntime=null;liveTournament=next;liveSave();render();notice('Torneo cargado en pausa.');});break;
 case 'live-recover':assertLivePaused();loadLive();break;
 case 'live-backup':assertLivePaused();if(confirm('¿Restaurar la copia automática anterior?'))loadLive(true);break;
 case 'live-undo':assertLivePaused();applyLive(L.undo(liveTournament));break;
 case 'live-rename':assertLivePaused();applyLive(L.rename(liveTournament,$('#live-edit-person').value,$('#live-edit-owner').value));break;
 case 'live-points':assertLivePaused();applyLive(L.adjust(liveTournament,$('#live-edit-person').value,+$('#live-edit-points').value,$('#live-points-reason').value));break;
 case 'live-correct':{assertLivePaused();const id=$('#live-edit-match').value,m=L.view(liveTournament).matches.find(m=>m.id===id),reason=$('#live-edit-reason').value.trim();if(!reason)throw new Error('Explica el motivo de la corrección.');if(!m)throw new Error('Elige un duelo disponible.');const side=$('#live-edit-winner').value;applyLive(L.commit(liveTournament,id,{aWins:+$('#live-edit-a').value,bWins:+$('#live-edit-b').value,draws:+$('#live-edit-draw').value,winnerId:side==='A'?m.aId:side==='B'?m.bId:null,games:[]},reason));break;}
 case 'live-replay':{assertLivePaused();const m=L.view(liveTournament).matches.find(m=>m.id===el.dataset.id),g=m?.result?.games[+el.dataset.game];if(!g)throw new Error('No hay una partida reproducible en este resultado manual.');const a=liveTournament.entries.find(e=>e.id===m.aId),b=liveTournament.entries.find(e=>e.id===m.bId);replay({a:a.code,b:b.code,config:{...liveTournament.settings,seed:g.seed,firstWarrior:g.firstWarrior,loadPoints:g.positions}});break;}
 case 'live-fullscreen':{if(document.fullscreenElement&&document.exitFullscreen){await document.exitFullscreen();document.body.dataset.broadcast='false';}else if(document.documentElement.requestFullscreen){document.body.dataset.broadcast='true';try{await document.documentElement.requestFullscreen();}catch{notice('Modo proyector activado dentro de la página.');}}else{document.body.dataset.broadcast=document.body.dataset.broadcast==='true'?'false':'true';notice('Modo proyector alternado.');}break;}

 }}
function selectHTML(id,items,value){return `<select id="${id}">${items.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select>`;}
function ruleSettings(d=tournamentDraft){return{coreSize:d.coreSize,maxCycles:d.maxCycles,maxProcesses:d.maxProcesses,maxLength:d.maxLength,minDistance:d.minDistance,pSpaceSize:d.pSpaceSize};}
function readTournamentDraft(){
 const fields={name:'t-name',format:'t-format',rounds:'t-rounds',swissRounds:'t-jornadas',coreSize:'t-core',maxCycles:'t-turns',maxProcesses:'t-processes',maxLength:'t-length',minDistance:'t-distance',pSpaceSize:'t-pspace',seed:'t-seed',drawPolicy:'t-draw',standings:'t-standings',knockoutTie:'t-knockout-tie',extraPairs:'t-extra-pairs',winPoints:'t-win',drawPoints:'t-equal',lossPoints:'t-loss',byePoints:'t-bye',banned:'t-banned',allowPSpace:'t-allow-pspace',qualifyCount:'t-qualify',countdown:'t-countdown',intermission:'t-intermission',autoAdvance:'t-auto',liveSpeed:'t-live-speed',stageStyle:'t-stage-style',stageColor:'t-stage-color',seeding:'t-seeding',liveAnnouncements:'t-live-announcements'};
 const numeric=new Set(['rounds','swissRounds','coreSize','maxCycles','maxProcesses','maxLength','minDistance','pSpaceSize','extraPairs','winPoints','drawPoints','lossPoints','byePoints','qualifyCount','countdown','intermission','liveSpeed']);
 for(const[k,id]of Object.entries(fields)){const el=$('#'+id);if(el)tournamentDraft[k]=['allowPSpace','autoAdvance'].includes(k)?el.checked:numeric.has(k)?+el.value:el.value;}
 tournamentDraft.name=String(tournamentDraft.name).slice(0,80);tournamentDraft.seed=String(tournamentDraft.seed).slice(0,100);saveSession();return tournamentDraft;
}
function validateParticipants(){let error='';try{L.options(tournamentDraft);E.validateSettings(ruleSettings());}catch(e){error=e.message;}
 const rows=tournamentEntries().map(w=>{const report=w.fileError?{ok:false,errors:[w.fileError]}:error?{ok:false,errors:[error]}:T.validate(w.code,ruleSettings(),L.admission(tournamentDraft));return{...w,report};});return{rows,error};}
function participantHTML(w){const v=w.report,selected=tournamentSelection.has(w.id);return `<div class="entrant ${v.ok?'accepted':'rejected'}"><label><input type="checkbox" data-participant="${esc(w.id)}" ${selected?'checked':''} ${v.ok?'':'disabled'}><span><strong>${esc(w.name)}</strong><span class="micro">${esc(w.filename||w.type)}</span></span></label><div class="entrant-status">${v.ok?`<span class="accent">✓ Cumple las reglas · ${v.length} instrucciones</span>`:`<span class="error-text">✕ ${esc(v.errors.join(' '))}</span>`}</div>${uploads.some(x=>x.id===w.id)?`<button class="ghost small" data-action="remove-upload" data-id="${esc(w.id)}" aria-label="Retirar ${esc(w.filename)}">Retirar</button>`:''}</div>`;}
function clampJornadas(){const count=validateParticipants().rows.filter(w=>w.report.ok&&tournamentSelection.has(w.id)).length;if(count>=2){const max=count%2?count:count-1;if(tournamentDraft.swissRounds>max){tournamentDraft.swissRounds=max;if($('#t-jornadas'))$('#t-jornadas').value=max;}}}
function participantsHTML(){const {rows,error}=validateParticipants(),valid=rows.filter(w=>w.report.ok&&tournamentSelection.has(w.id)),uploaded=rows.filter(w=>uploads.some(u=>u.id===w.id));return `${error?`<div class="feedback error">${esc(error)}</div>`:''}<div class="flex between"><h3>Archivos del torneo</h3><span class="pill">${valid.length} / 32 VÁLIDOS</span></div>${uploaded.length?uploaded.map(participantHTML).join(''):'<p class="micro">Sube los .red de los participantes para comenzar.</p>'}<details class="section"><summary>Incluir guerreros de la biblioteca</summary><button class="small section" data-action="tournament-examples">Añadir cuatro ejemplos</button><div class="check-list">${rows.filter(w=>!uploads.some(u=>u.id===w.id)).map(participantHTML).join('')}</div></details><p class="micro">Los archivos rechazados quedan fuera. Las reglas se vuelven a comprobar antes de iniciar el torneo.</p>`;}
function tournamentHTML(){if(liveTournament)return liveHTML();const t=tournamentProgress||tournament;if(!t)return `<div class="empty"><div class="icon-box" style="margin:auto">♜</div><strong>Tu torneo empieza con tus guerreros.</strong><p>Sube archivos .red, elige las reglas y crea los emparejamientos.</p></div>`;
 const opts={...T.DEFAULTS,...t.options,format:t.format},rows=t.rows.map(r=>({buchholz:0,sonneborn:0,matchWins:0,byes:0,...r})),sorted=T.rank(rows,opts.standings),leaders=t.leaders||[];
 return `<div class="flex between"><h2>${tournamentRunning?'Torneo en curso…':esc(t.name||'Clasificación')}</h2><span class="pill">${formatName(t.format)} · ${t.matches.length} DUELOS</span></div>${t.champion?`<div class="result finished">♜ Campeón: ${esc(rows.find(r=>r.id===t.champion)?.name)}</div>`:!tournamentRunning&&leaders.length>1?`<div class="result finished">Empate en cabeza: ${leaders.map(id=>esc(rows.find(r=>r.id===id)?.name)).join(' · ')}</div>`:''}<p class="micro">${opts.winPoints} por victoria · ${opts.drawPoints} por empate · ${opts.lossPoints} por derrota · ${opts.byePoints} por descanso. Puntuación por duelo. Desempate: ${esc({buchholz:'Buchholz',sonneborn:'Sonneborn–Berger',wins:'duelos ganados',name:'sin desempate deportivo'}[opts.standings])}.</p><div class="table-wrap"><table><thead><tr><th>#</th><th>Guerrero</th><th>Pts</th><th>Buchholz</th><th>S–B</th><th>V / E / D</th><th>Partidas</th><th>Descansos</th></tr></thead><tbody>${sorted.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td><strong>${r.points}</strong></td><td>${r.buchholz}</td><td>${r.sonneborn}</td><td>${r.wins} / ${r.draws} / ${r.losses}</td><td>${r.played}</td><td>${r.byes}</td></tr>`).join('')}</tbody></table></div>${(t.stages||[]).filter(s=>s.bye||s.byes?.length).map(s=>`<p class="micro section">${esc(s.label)} · Descanso: ${[...(s.byes||[]),...(s.bye?[s.bye]:[])].map(id=>esc(rows.find(r=>r.id===id)?.name)).join(', ')}</p>`).join('')}<h3 class="section">Emparejamientos y partidas</h3>${t.matches.map((m,i)=>`<details class="match-card"><summary>${m.stage?`J${m.stage} · `:''}${esc(m.a)} <span class="accent">${m.aWins} – ${m.bWins}</span> ${esc(m.b)} · ${m.draws} empates</summary>${m.repeated?'<p>Revancha: no se encontró un emparejamiento completo sin repetir rivales.</p>':''}${m.extraGames?`<p>${m.extraGames} partidas extra de desempate.</p>`:''}${m.tiebreak?`<p>Persistió el empate: ${esc(rows.find(r=>r.id===m.winnerId)?.name)} avanza por sorteo reproducible.</p>`:''}<button class="small" data-action="announce-match" data-match="${i}">Ver anuncio del duelo</button>${m.games.map((g,j)=>`<div class="flex between" style="padding:5px 0"><span class="micro">P${j+1} · ${esc(g.winner==='A'?m.a:g.winner==='B'?m.b:'Empate')} · ${g.turns} turnos</span><div class="flex"><button class="small" data-action="announce-game" data-match="${i}" data-game="${j}" aria-label="Ver resultado de la partida ${j+1}">Resultado</button><button class="small" data-action="replay-tournament" data-match="${i}" data-game="${j}">Reproducir ↗</button></div></div>`).join('')}</details>`).join('')}`;}
function tournaments(){const d=tournamentDraft;
 return title('Torneos','Sube tus .red. Define las reglas. Elige los emparejamientos.',`<div class="flex"><button data-action="live-import">Cargar torneo JSON</button><button data-action="live-recover">Recuperar guardado</button><button data-action="live-backup">Copia anterior</button><button data-action="export-tournament" ${!tournament?'disabled':''}>Exportar resultados</button><button data-action="cancel-tournament" ${!tournamentRunning?'disabled':''}>Detener torneo</button></div>`)+`<div class="grid tournament-layout"><aside class="panel tournament-setup"><h2>Preparar competición</h2><label>Nombre<input id="t-name" maxlength="80" value="${esc(d.name)}"></label><label class="section">Emparejamiento${selectHTML('t-format',[['knockout','Eliminatoria · cuadro directo'],['double','Doble eliminación · recuperación'],['groups','Grupos de cuatro + fase final'],['league','Liguilla · todos contra todos'],['swiss','Suizo · puntuaciones similares'],['random','Aleatorio por jornadas']],d.format)}</label><div class="config-fields section"><label>Partidas por duelo${selectHTML('t-rounds',[2,4,8,16].map(n=>[n,n]),d.rounds)}</label><label>Jornadas suizo / aleatorio<input id="t-jornadas" type="number" min="1" max="32" value="${d.swissRounds}"></label></div><label class="section">Clasificados a la fase final (liguilla / suizo)${selectHTML('t-qualify',[[0,'Sin fase final'],[2,'2 · Final'],[4,'4 · Semifinales'],[8,'8 · Cuartos'],[16,'16 · Octavos'],[32,'32 · Cuadro completo']],d.qualifyCount)}</label><label class="section">Orden inicial${selectHTML('t-seeding',[['shuffle','Sorteo con la semilla'],['ordered','Orden de inscripción']],d.seeding)}</label><details class="section" open><summary>Presentación y ritmo</summary><div class="config-fields section"><label>Cuenta atrás (segundos)<input id="t-countdown" type="number" min="0" max="10" value="${d.countdown}"></label><label>Pausa entre duelos (ms)<input id="t-intermission" type="number" min="0" max="15000" value="${d.intermission}"></label></div><label class="section">Efecto de escenario${selectHTML('t-stage-style',[['spotlight','Focos suaves'],['rift','Energía del núcleo'],['off','Sin animación']],d.stageStyle)}</label><label class="section">Anuncios de resultado${selectHTML('t-live-announcements',[['duels','Cada duelo y campeón'],['games','Cada partida y campeón'],['final','Solo campeón'],['off','Desactivados']],d.liveAnnouncements)}</label><label class="section">Color del escenario<input id="t-stage-color" type="color" value="${d.stageColor}"></label><label class="section">Velocidad${selectHTML('t-live-speed',[[20,'Lenta'],[200,'Normal'],[2000,'Rápida'],[10000,'Turbo']],d.liveSpeed)}</label><label class="inline section"><input id="t-auto" type="checkbox" ${d.autoAdvance?'checked':''}> Encadenar duelos automáticamente</label><p class="micro">Puedes iniciar cada cruce a mano. Los ganadores, BYE y clasificados avanzan automáticamente.</p></details><details class="section" open><summary>Reglas del núcleo</summary><div class="config-fields section">${[['coreSize','t-core','Celdas',32,32768],['maxCycles','t-turns','Límite de turnos',1,500000],['maxProcesses','t-processes','Procesos máximos',1,8000],['maxLength','t-length','Longitud máxima',1,1000],['minDistance','t-distance','Distancia mínima',0,32768],['pSpaceSize','t-pspace','Tamaño de P-space',1,4096]].map(([k,id,n,min,max])=>`<label>${n}<input id="${id}" type="number" min="${min}" max="${max}" value="${d[k]}"></label>`).join('')}</div><label class="inline section"><input id="t-allow-pspace" type="checkbox" ${d.allowPSpace?'checked':''}> Permitir LDP, STP y PIN</label><label class="section">Instrucciones prohibidas<input id="t-banned" value="${esc(d.banned)}" maxlength="150" placeholder="Ej. SPL, MUL"></label><label class="section">Semilla<input id="t-seed" maxlength="100" value="${esc(d.seed)}" placeholder="Vacía = nuevo sorteo"></label></details><details class="section"><summary>Puntuación y empates</summary><div class="config-fields section">${[['winPoints','t-win','Victoria'],['drawPoints','t-equal','Empate'],['lossPoints','t-loss','Derrota'],['byePoints','t-bye','Descanso']].map(([k,id,n])=>`<label>${n}<input id="${id}" type="number" min="0" max="100" value="${d[k]}"></label>`).join('')}</div><label class="section">Si ambos sobreviven al límite${selectHTML('t-draw',[['draw','Mantener empate'],['territory','Gana quien escribió más celdas'],['processes','Gana quien tiene más procesos']],d.drawPolicy)}</label><p class="micro">Celdas y procesos son variantes opcionales. En Core War clásico, ambos supervivientes empatan.</p><label class="section">Desempate de clasificación${selectHTML('t-standings',[['buchholz','Buchholz · suma de puntos de rivales'],['sonneborn','Sonneborn–Berger · resultados y rivales'],['wins','Número de duelos ganados'],['name','Mantener empate en puntos']],d.standings)}</label><label class="section">Empate en una eliminatoria${selectHTML('t-knockout-tie',[['extra','Partidas extra; si persiste, sorteo'],['seeded','Sorteo reproducible']],d.knockoutTie)}</label><label class="section">Pares extra como máximo<input id="t-extra-pairs" type="number" min="0" max="8" value="${d.extraPairs}"></label></details><div class="note micro">Cada par de partidas usa las mismas posiciones y alterna quién empieza. El suizo evita repetir rivales cuando existe un emparejamiento completo. Si hay un número impar, descansa un guerrero, priorizando a quienes aún no han descansado.</div><button id="t-start" class="primary" data-action="prepare-live" ${tournamentRunning?'disabled':''} style="width:100%">${tournamentRunning?'Calculando partidas…':'Validar y dibujar el cuadro ↗'}</button><p class="micro section">Estos ajustes preparan un cuadro nuevo. Los controles del cuadro gestionan la emisión y las correcciones del torneo abierto.</p><a href="#settings" class="button small section">Personalizar anuncios y núcleo</a></aside><section><div class="panel"><div id="tournament-drop" class="upload-zone" tabindex="0" role="button" aria-label="Subir archivos Redcode"><span class="icon-box">↑</span><h2>Trae tus guerreros</h2><p>Arrastra tus archivos .red o selecciónalos de tu equipo.<br>Puedes subir varios a la vez.</p><button class="primary" data-action="upload-tournament">Seleccionar .red</button></div><div id="participants" class="section">${participantsHTML()}</div></div><div class="panel section" id="tournament-results" role="region" aria-label="Torneo y clasificación">${tournamentHTML()}</div><div class="panel section"><h2>Torneos guardados</h2>${data.tournaments.length?data.tournaments.map((t,i)=>`<div class="list-row"><div><strong>${esc(t.name)}</strong><span>${t.rows?.length||0} guerreros · ${esc(formatName(t.format))}</span></div><button class="small" data-action="open-tournament" data-index="${i}">Abrir</button></div>`).join(''):'<p class="micro">Se conservan los diez últimos torneos terminados.</p>'}</div></section></div>`;
}
async function addTournamentFiles(files){if(tournamentRunning)throw new Error('Detén el torneo antes de cambiar participantes.');if(uploads.length+files.length>100)throw new Error('Puedes conservar hasta 100 archivos en esta sesión y seleccionar hasta 32.');
 const reads=await Promise.all(Array.from(files).map(async file=>{let code='',fileError='';try{if(!/\.(red|rc)$/i.test(file.name))throw new Error('Selecciona un archivo .red o .rc.');if(file.size>100000)throw new Error('El archivo supera 100 KB.');code=await file.text();if(code.length>100000)throw new Error('Código demasiado grande.');}catch(e){fileError=e.message;}
 const name=(code.match(/^\s*;name\s+(.+)$/im)?.[1]||file.name.replace(/\.[^.]+$/,'')).trim().slice(0,80);return{id:'upload-'+crypto.getRandomValues(new Uint32Array(1))[0]+'-'+(++uploadCounter),name,filename:String(file.name).slice(0,120),code,fileError,type:'Archivo .red',level:'Personal'};}));
 uploads.push(...reads);const reports=validateParticipants().rows;for(const w of reads){if(reports.find(r=>r.id===w.id)?.report.ok)tournamentSelection.add(w.id);}clampJornadas();saveSession();saveUploads();if(route==='tournaments')render();const accepted=reads.filter(w=>reports.find(r=>r.id===w.id)?.report.ok).length;notice(`${accepted} archivo${accepted===1?'':'s'} aceptado${accepted===1?'':'s'} · ${reads.length-accepted} rechazado${reads.length-accepted===1?'':'s'}.`);
}
function uploadTournament(){const input=document.createElement('input');input.type='file';input.accept='.red,.rc';input.multiple=true;input.onchange=()=>addTournamentFiles(input.files).catch(e=>notice(e.message));input.click();}
function setupTournamentDrop(){const zone=$('#tournament-drop');if(!zone)return;zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');addTournamentFiles(e.dataTransfer.files).catch(err=>notice(err.message));});zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();uploadTournament();}});}
function prefCheck(k,label){return `<label class="inline"><input type="checkbox" id="pref-${k}" ${data.prefs[k]?'checked':''}> ${esc(label)}</label>`;}
function prefRange(k,label,min,max,step=1,unit=''){return `<label>${esc(label)} <span class="micro" id="pref-value-${k}">${data.prefs[k]}${unit}</span><input type="range" id="pref-${k}" min="${min}" max="${max}" step="${step}" value="${data.prefs[k]}"></label>`;}
function visualControls(){const p=data.prefs;return `<section class="panel options"><h2>Núcleo</h2><label>Forma${selectHTML('pref-coreShape',[['square','Cuadrado'],['wide','Panorámico']],p.coreShape)}</label><label>Celdas${selectHTML('pref-cellShape',[['square','Cuadradas'],['rounded','Esquinas redondeadas'],['circle','Circulares']],p.cellShape)}</label>${prefRange('coreWidth','Anchura máxima',300,1000,10,' px')}${prefRange('cellGap','Espacio entre celdas',0,4,.5,' px')}<label>Color de memoria vacía<input id="pref-emptyColor" type="color" value="${p.emptyColor}"></label>${prefCheck('coreMotion','Actualizar la memoria en directo')}${prefCheck('showProcesses','Marcar posiciones de los procesos')}${prefCheck('trails','Mostrar estelas de actividad')}${prefRange('trailLength','Duración de las estelas',20,1000,20,' turnos')}<p class="micro">Sin actualización en directo, el núcleo permanece quieto mientras se ejecuta. Puedes refrescarlo, avanzar un turno o pausarlo para ver su estado.</p></section><section class="panel options"><h2>Resultados en el centro</h2>${prefCheck('arenaFx','Mostrar anuncio al terminar una partida')}<label>En torneos${selectHTML('pref-tournamentFx',[['final','Solo al finalizar el torneo'],['duels','Cada duelo y final del torneo'],['games','Cada partida y final del torneo'],['off','Desactivados']],p.tournamentFx)}</label><label>Efecto${selectHTML('pref-resultStyle',[['orbit','Órbita'],['pulse','Pulso suave'],['slide','Entrada lateral'],['still','Sin movimiento']],p.resultStyle)}</label>${prefRange('resultDuration','Duración',0,15000,500,' ms')}<p class="micro">0 = permanece hasta que lo cierres.</p>${prefRange('resultSize','Tamaño del nombre',24,72,2,' px')}${prefRange('resultOpacity','Oscurecer fondo',10,95,5,'%')}${prefRange('resultIntensity','Intensidad del movimiento',0,100,5,'%')}${prefRange('resultGlow','Brillo',0,100,5,'%')}${prefRange('resultParticles','Partículas suaves',0,60,2)}<div class="config-fields"><label>Victoria A<input type="color" id="pref-winA" value="${p.winA}"></label><label>Victoria B<input type="color" id="pref-winB" value="${p.winB}"></label><label>Empate<input type="color" id="pref-drawColor" value="${p.drawColor}"></label></div><div class="controls"><button data-action="preview-win">Probar victoria</button><button data-action="preview-draw">Probar empate</button></div></section><section class="panel options"><h2>Fondo discreto</h2><label>Animación${selectHTML('pref-background',[['grid','Retícula en movimiento'],['orbits','Órbitas suaves'],['off','Desactivada']],p.background)}</label>${prefRange('backgroundOpacity','Intensidad',0,15,1,'%')}${prefRange('backgroundSpeed','Tiempo de recorrido',15,180,5,' s')}<p class="micro">El movimiento queda detrás de las zonas libres; las tarjetas conservan un fondo sólido para facilitar la lectura.</p><div class="note">Los ajustes visuales y las reglas de partida y torneo se guardan en cookies de sesión. Los archivos .red subidos se conservan en esta pestaña durante la sesión.</div><button data-action="disable-motion">Desactivar todo el movimiento</button></section>`;}
function settings(){return title('Personalización','Tu arena, a tu manera. Ajustes para esta sesión.')+`<div class="grid three"><section class="panel options"><h2>Apariencia</h2><label>Tema${selectHTML('pref-theme',[['dark','Terminal · verde'],['violet','Órbita · violeta'],['light','Luz · claro']],data.prefs.theme)}</label><label>Tamaño del texto${selectHTML('pref-size',[16,18,20,22].map(n=>[n,n+' px']),data.prefs.size)}</label><label>Color del guerrero A<input type="color" id="pref-a" value="${data.prefs.a}"></label><label>Color del guerrero B<input type="color" id="pref-b" value="${data.prefs.b}"></label>${prefCheck('reduced','Reducir todas las animaciones')}${prefCheck('contrast','Aumentar contraste')}<button data-action="reset-prefs">Restablecer apariencia</button></section><section class="panel"><h2>Tus datos</h2><p>Sin cuentas ni registro. Tus guerreros guardados, progreso y resultados se conservan en este navegador.</p><div class="list-row"><strong>${data.custom.length}</strong><span>guerreros personales</span></div><div class="list-row"><strong>${countSolved()}</strong><span>puzles resueltos</span></div><div class="list-row"><strong>${data.lessons.length} / 9</strong><span>lecciones completadas</span></div><div class="controls section"><button class="primary" data-action="export-data">Exportar todo</button><button data-action="import-data">Importar copia</button></div><p class="micro section">Importar reemplaza los datos tras confirmar. Exporta una copia antes de cambiar de equipo o borrar los datos del navegador. Las preferencias de esta sesión se incluyen en la copia.</p>${storageIssue?'<div class="feedback error">El guardado local no está disponible. Exporta tus datos antes de cerrar.</div>':''}</section><section class="panel"><div class="icon-box">◈</div><h2 style="margin-top:18px">OGUN</h2><p>Operaciones de Guerreros en un Núcleo.</p><p>Un espacio para aprender, experimentar y disfrutar de Core War en castellano.</p><div class="note">Creado por <strong>Sara y Pascal</strong>.</div><a href="#learn" class="button">Volver al aprendizaje ↗</a></section>${visualControls()}</div>`;}
function showResult(result,context='arena',force=false){if(!force&&(context==='arena'&&!data.prefs.arenaFx||context==='tournament'&&data.prefs.tournamentFx==='off'))return;
 if(resultQueue.length>=128)resultQueue.shift();resultQueue.push(result);if(!resultActive)nextResult();}
function nextResult(){const layer=$('#result-layer');if(!layer||!resultQueue.length)return;const r=resultQueue.shift(),p=data.prefs,draw=r.winner==='Empate',name=r.name||(draw?[r.a,r.b].filter(Boolean).join(' · '):r.winner==='A'?r.a:r.b),color=draw?p.drawColor:r.winner==='B'?p.winB:p.winA;
 if(!resultActive)resultReturnFocus=document.activeElement;resultActive=true;resultDeadline=p.resultDuration?Date.now()+p.resultDuration:0;layer.classList.remove('hidden');layer.dataset.effect=p.reduced||p.resultIntensity===0?'still':p.resultStyle;
 layer.style.setProperty('--result-color',color);layer.style.setProperty('--result-size',p.resultSize+'px');layer.style.setProperty('--result-opacity',p.resultOpacity/100);layer.style.setProperty('--result-glow',p.resultGlow/100);layer.style.setProperty('--result-move',p.resultIntensity/100);layer.innerHTML=`<div class="result-scene"><div class="result-orbit" aria-hidden="true"></div><div class="result-particles" aria-hidden="true">${Array.from({length:p.reduced?0:p.resultParticles},(_,i)=>`<i style="--i:${i};--angle:${i*137.508}deg;--distance:${70+(i%6)*22}px;--delay:${i%5*.1}s"></i>`).join('')}</div><div class="result-emblem" aria-hidden="true">${draw?'＝':'♜'}</div><div class="eyebrow">${esc(r.label||(draw?'EMPATE':'VICTORIA'))}</div><h2 id="result-name">${esc(name||'Empate')}</h2><p>${esc(r.reason||'')}</p><div class="controls"><button id="result-close" class="primary" data-result="close">${resultQueue.length?'Siguiente resultado':'Continuar'}</button><button id="result-skip" data-result="skip">Cerrar anuncios</button></div><span class="micro">${p.resultDuration?'Se cierra automáticamente · ':''}Escape para cerrar</span></div>`;
 $('#result-close')?.focus();}
function dismissResult(all=false){const layer=$('#result-layer');if(all)resultQueue=[];if(resultQueue.length&&!all){nextResult();return;}resultActive=false;resultDeadline=0;layer?.classList.add('hidden');if(resultReturnFocus?.isConnected)resultReturnFocus.focus({preventScroll:true});else $('#main')?.focus({preventScroll:true});resultReturnFocus=null;}
function announceTournament(t){if(data.prefs.tournamentFx==='off')return;const leader=t.rows.find(r=>r.id===t.champion),names=(t.leaders||[]).map(id=>t.rows.find(r=>r.id===id)?.name).filter(Boolean);showResult({winner:leader?'A':'Empate',name:leader?.name||names.join(' · '),label:leader?'CAMPEÓN DEL TORNEO':'TORNEO EMPATADO',reason:t.name},'tournament');}
function render(){
 W.dispose();running=false;puzzleFeedback='';applyPrefs();
 root.innerHTML=header()+`<main id="main" tabindex="-1">${({home,arena,workshop:W.html,puzzles,learn,warriors,tournaments,settings}[route]||home)()}</main><footer><span><strong>OGUN</strong> · Operaciones de Guerreros en un Núcleo</span><span>Creado por Sara y Pascal · Aprende. Programa. Compite.</span></footer>`;
 document.title=`${({home:'Core War en castellano',arena:'Arena',workshop:'Taller de guerreros',puzzles:'Puzles',learn:'Aprender',warriors:'Guerreros',tournaments:'Torneos',settings:'Personalización'})[route]} · OGUN`;
 if(route==='arena'||route==='workshop')W.mount(route,{sources:()=>data.draft,motion:()=>!data.prefs.reduced&&data.prefs.coreMotion,update:(id,src)=>{data.draft[id]=src;running=false;battle=null;save();},custom:()=>data.custom,render,notice,download,pickFile,navigate:go,useSource:src=>{data.draft.a=src;for(const k of ['coreSize','maxCycles','maxProcesses','maxLength','minDistance','pSpaceSize'])config[k]=OgunRating.SETTINGS[k];config.firstWarrior='random';config.drawPolicy='draw';config.seed='';delete config.loadPoints;battle=null;save();go('arena');notice('Guerrero enviado a A con las reglas de la forja: núcleo de 8.000 celdas.');},saveWarrior:src=>{const w=E.compileWarrior(src,OgunRating.SETTINGS);if(data.custom.length>=100)throw new Error('Máximo 100 guerreros guardados.');data.custom.push({id:'custom-'+Date.now(),name:w.metadata.name,type:'Personal',description:'Forjado en el taller.',code:src,level:'Personal'});save();notice('Guerrero guardado en tu biblioteca.');}});
 if(route==='home')setupDemo();
 if(route==='arena'){setupCore();updateBattle();}
 if(route==='tournaments')setupTournamentDrop();
 updateCountdown();
}
function parseHash(){const hash=location.hash.slice(1);if(hash.startsWith('battle=')){try{if(hash.length>150000)throw new Error('Enlace demasiado largo');const raw=decodeURIComponent(escape(atob(hash.slice(7))));const d=JSON.parse(raw);importBattle(d);route='arena';history.replaceState(null,'','#arena');}catch(e){notice('No se pudo abrir la partida: '+e.message);route='arena';}}else route=['home','arena','workshop','puzzles','learn','warriors','tournaments','settings'].includes(hash)?hash:'home';}
function go(r){if(route===r){render();return;}location.hash=r;}
function readConfig(){for(const k of ['coreSize','maxCycles','maxProcesses','maxLength','minDistance']){const field=$('#cfg-'+k);if(field)config[k]=+field.value;}if($('#cfg-seed'))config.seed=$('#cfg-seed').value;if($('#cfg-firstWarrior'))config.firstWarrior=$('#cfg-firstWarrior').value;if($('#cfg-drawPolicy'))config.drawPolicy=$('#cfg-drawPolicy').value;E.validateSettings(config);saveSession();}
function prepare(newPosition=false){readConfig();const cfg={...config};if(newPosition){cfg.seed='';delete cfg.loadPoints;delete config.loadPoints;config.seed='';$('#cfg-seed').value='';}battle=E.createBattle(E.compileWarrior(data.draft.a,cfg),E.compileWarrior(data.draft.b,cfg),cfg);battle.original={a:data.draft.a,b:data.draft.b,config:{...battle.settings,firstWarrior:battle.turn===0?'A':'B'}};battle.recorded=false;updateBattle();save();}
function replay(original){running=false;const o=original||battle?.original;if(!o){prepare();return;}config={...config,...o.config};data.draft={a:o.a,b:o.b};save();if(route!=='arena'){go('arena');}else render();battle=E.createBattle(E.compileWarrior(o.a,config),E.compileWarrior(o.b,config),config);battle.original=structuredClone(o);battle.recorded=false;updateBattle();}
function recordBattle(){if(!battle?.halted||battle.recorded)return;battle.recorded=true;const a=battle.warriors[0].name,b=battle.warriors[1].name;data.history.unshift({a,b,result:battle.winner==='Empate'?'Empate':'Gana '+(battle.winner==='A'?a:b),turns:battle.cycle,original:battle.original});data.history=data.history.slice(0,30);save();if($('#history-list'))$('#history-list').innerHTML=historyHTML();}
function updateBattle(){if(!$('#core-canvas'))return;if(data.prefs.coreMotion||!running||battle?.halted)drawCore($('#core-canvas'),battle);if(!battle)return;$('#turn-count').textContent=battle.cycle.toLocaleString('es');$('#process-a').textContent=battle.queues.A.length;$('#process-b').textContent=battle.queues.B.length;$('#battle-meter').style.width=100*battle.cycle/battle.settings.maxCycles+'%';$('#core-size').textContent=battle.settings.coreSize+' CELDAS';const result=$('#battle-result');result.classList.toggle('finished',battle.halted);result.textContent=battle.halted?(battle.winner==='Empate'?'Empate. '+battle.winReason:'Gana '+battle.warriors.find(w=>w.id===battle.winner).name+'. '+battle.winReason):running?'Batalla en curso.':battle.cycle?'Batalla en pausa.':'Guerreros cargados. Preparados para combatir.';$('#run-btn').textContent=running?'Ⅱ Pausar':battle.halted?'▶ Nueva batalla':'▶ Iniciar batalla';$('#load-info').textContent=`Semilla: ${battle.settings.seed} · A @${battle.warriors[0].start} · B @${battle.warriors[1].start} · Empieza ${battle.original.config.firstWarrior}`;$('#trace').innerHTML=battle.debugLog.slice(0,20).map(g=>`<div><strong>${g.warrior} @${g.ip}</strong> · T${g.cycle+1}<br>${esc(g.instruction)}<br>${esc(g.summary)}</div>`).join('')||'Sin movimientos todavía.';$('#inspect-index').max=battle.settings.coreSize-1;inspect(+$('#inspect-index').value||0);recordBattle();if(battle.halted&&!battle.resultShown){battle.resultShown=true;showResult({winner:battle.winner,a:battle.warriors[0].name,b:battle.warriors[1].name,reason:battle.winReason},'arena');}}
function inspect(index){if(!battle||!$('#inspect-text'))return;index=Math.max(0,Math.min(battle.settings.coreSize-1,index));const cell=battle.core[index];$('#inspect-text').textContent=`@${index} · ${E.formatInstruction(cell)} · ${cell.owner?'Escrito por '+cell.owner:'Memoria inicial'}${battle.queues.A.includes(index)?' · Próximo A':''}${battle.queues.B.includes(index)?' · Próximo B':''}`;}
function setupCore(){const canvas=$('#core-canvas');canvas.addEventListener('pointermove',event=>{if(!battle)return;const rect=canvas.getBoundingClientRect(),g=S.geometry(battle.core.length,data.prefs.coreShape),x=Math.floor((event.clientX-rect.left)/rect.width*g.cols),y=Math.floor((event.clientY-rect.top)/rect.height*g.rows),index=y*g.cols+x;if(index<battle.core.length&&x>=0&&y>=0){$('#inspect-index').value=index;inspect(index);}});}
function drawCore(canvas,state){if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;const n=state?.core.length||config.coreSize,p=data.prefs,g=S.geometry(n,p.coreShape);if(canvas.width!==g.width)canvas.width=g.width;if(canvas.height!==g.height)canvas.height=g.height;const cw=canvas.width/g.cols,ch=canvas.height/g.rows,a=p.a,b=p.b,gap=Math.min(p.cellGap,cw/4,ch/4);
 ctx.globalAlpha=1;ctx.fillStyle=p.theme==='light'?'#f4f6f7':'#101820';ctx.fillRect(0,0,canvas.width,canvas.height);
 function cell(i,color,alpha=1,mark=false){const x=i%g.cols*cw+gap,y=Math.floor(i/g.cols)*ch+gap,w=cw-gap*2,h=ch-gap*2;ctx.globalAlpha=alpha;ctx.fillStyle=color;if(p.cellShape==='circle'){ctx.beginPath();ctx.arc(x+w/2,y+h/2,Math.max(1,Math.min(w,h)/2),0,Math.PI*2);ctx.fill();}else if(p.cellShape==='rounded'&&ctx.roundRect){ctx.beginPath();ctx.roundRect(x,y,w,h,Math.min(w,h)*.2);ctx.fill();}else ctx.fillRect(x,y,w,h);if(mark){ctx.globalAlpha=1;ctx.fillStyle=p.theme==='light'?'#000':'#fff';ctx.fillRect(x+w*.35,y+h*.35,Math.max(1,w*.3),Math.max(1,h*.3));}}
 for(let i=0;i<n;i++){const owner=state?.core[i].owner;cell(i,owner==='A'?a:owner==='B'?b:p.emptyColor,owner ? .48 : 1);if(state&&p.trails&&p.coreMotion&&!p.reduced){const age=state.cycle-state.visual.lastTouchedCycle[i];if(age<p.trailLength&&state.visual.lastTouchedCycle[i]>=0){const by=state.visual.lastWriteBy[i]||state.visual.lastExecBy[i];cell(i,by==='A'?a:b,Math.max(.3,1-age/p.trailLength));}}}
 if(state&&p.showProcesses)for(const[id,color]of [['A',a],['B',b]])for(const i of state.queues[id].slice(0,128))cell(i,color,1,true);ctx.globalAlpha=1;
}
function setupDemo(){const cfg={...config,loadPoints:undefined,drawPolicy:'draw',coreSize:1024,minDistance:100,maxCycles:16000,seed:'ogun-demo',firstWarrior:'A'};demo=E.createBattle(E.compileWarrior(D.warriors[0].code,cfg),E.compileWarrior(D.warriors[1].code,cfg),cfg);E.runSteps(demo,300);drawCore($('#demo-canvas'),demo);}
function updateCountdown(){if(!$('#countdown'))return;const now=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now),vals=Object.fromEntries(parts.map(p=>[p.type,p.value]));let left=86400-(+vals.hour*3600+ +vals.minute*60+ +vals.second);$('#countdown').textContent=`${Math.floor(left/3600)}h ${Math.floor(left%3600/60)}m`;}
function importBattle(d){if(!d||d.type!=='ogun-battle'||typeof d.a!=='string'||typeof d.b!=='string')throw new Error('No es una partida OGUN.');if(d.a.length>100000||d.b.length>100000)throw new Error('Código demasiado grande');const cfg={...E.DEFAULT_SETTINGS,...d.config};E.validateSettings(cfg);if(String(cfg.seed||'').length>256)throw new Error('Semilla demasiado larga');const prepared=E.createBattle(E.compileWarrior(d.a,cfg),E.compileWarrior(d.b,cfg),cfg);data.draft={a:d.a,b:d.b};config=cfg;battle=prepared;battle.original={a:d.a,b:d.b,config:{...prepared.settings,firstWarrior:prepared.turn===0?'A':'B'}};save();}
function pickFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>50000000)throw new Error('El archivo supera 50 MB.');await callback(await file.text(),file.name);}catch(e){notice(e.message);}};input.click();}
function setPuzzleFeedback(text,ok=true){puzzleFeedback=`<div class="feedback ${ok?'':'error'}">${esc(text)}</div>`;if($('#puzzle-feedback'))$('#puzzle-feedback').innerHTML=puzzleFeedback;}
async function action(name,el){
 if(name.startsWith('work-'))return W.action(name,el);
 if(name.startsWith('live-')||name==='prepare-live')return liveAction(name,el);
 switch(name){
 case 'check-puzzle':{const v=$('#answer').value,r=C.check(currentPuzzle,v);setPuzzleFeedback(r.feedback+(r.ok?' '+currentPuzzle.explanation:''),r.ok);if(r.ok){data.solved[currentPuzzle.id]=true;save();}break;}
 case 'hint-puzzle':setPuzzleFeedback(currentPuzzle.hint);break;
 case 'solution-puzzle':$('#answer').value=currentPuzzle.solution;setPuzzleFeedback('Solución: '+currentPuzzle.solution+'. '+currentPuzzle.explanation+' Comprueba el código para completar el ejercicio.');break;
 case 'daily-slot':dailySlot=+el.dataset.slot;archiveMode=false;currentPuzzle=C.daily(puzzleDate,dailySlot);render();break;
 case 'new-puzzle':archiveMode=true;practiceCount++;currentPuzzle=C.puzzle(`practice:${Date.now()}:${practiceCount}`,Math.floor(Math.random()*5));render();break;
 case 'lesson':lesson=+el.dataset.index;render();break;
 case 'lesson-prev':lesson=Math.max(0,lesson-1);render();break;
 case 'lesson-next':lesson=Math.min(8,lesson+1);render();break;
 case 'lesson-complete':if(!data.lessons.includes(lesson))data.lessons.push(lesson);save();render();break;
 case 'run-battle':if(running){running=false;}else{if(!battle||battle.halted)prepare();running=true;}updateBattle();break;
 case 'step-battle':case 'batch-battle':running=false;if(!battle||battle.halted)prepare();E.runSteps(battle,name==='step-battle'?1:100);updateBattle();break;
 case 'new-battle':dismissResult(true);running=false;prepare(true);break;
 case 'replay-battle':dismissResult(true);replay();break;
 case 'validate-code':{readConfig();const id=el.dataset.side,w=E.compileWarrior(data.draft[id],config);$('#validation-'+id).textContent=`✓ ${w.metadata.name} · ${w.length} instrucciones · entrada ${w.entryPoint}`;break;}
 case 'save-warrior':{readConfig();const id=el.dataset.side,w=E.compileWarrior(data.draft[id],config);if(data.custom.length>=100)throw new Error('Máximo 100 guerreros guardados.');data.custom.push({id:'custom-'+Date.now(),name:w.metadata.name,type:'Personal',description:'Tu estrategia, lista para competir.',code:data.draft[id],level:'Personal'});save();notice('Guerrero guardado en tu biblioteca.');render();break;}
 case 'load-warrior':{const w=allWarriors().find(w=>w.id===el.dataset.id);if(!w)return;data.draft[el.dataset.side]=w.code;battle=null;save();go('arena');break;}
 case 'new-warrior':data.draft.a=';redcode-94\n;name Mi guerrero\n;author \nORG start\nstart MOV.I 0, 1\nEND start';battle=null;save();go('arena');break;
 case 'delete-warrior':{const w=data.custom.find(w=>w.id===el.dataset.id);if(!w||!confirm(`¿Eliminar ${w.name} de tu biblioteca?`))return;data.custom=data.custom.filter(x=>x.id!==w.id);tournamentSelection.delete(w.id);save();render();break;}
 case 'export-warrior':download('guerrero-'+el.dataset.side.toUpperCase()+'.red',data.draft[el.dataset.side]);break;
 case 'import-warrior':{const id=el.dataset.side;pickFile('.red,.rc,.txt',text=>{if(text.length>100000)throw new Error('Código demasiado grande');readConfig();E.compileWarrior(text,config);data.draft[id]=text;battle=null;save();render();notice('Guerrero cargado.');});break;}
 case 'history-replay':{const g=data.history[+el.dataset.index];if(!g?.original)throw new Error('La partida no contiene código reproducible');replay(g.original);break;}
 case 'share-battle':{if(!battle)prepare();const o=battle.original,d={type:'ogun-battle',...o},url=location.href.split('#')[0]+'#battle='+btoa(unescape(encodeURIComponent(JSON.stringify(d))));if(url.length>150000)throw new Error('La partida es demasiado grande para un enlace. Expórtala como archivo.');try{await navigator.clipboard.writeText(url);notice('Enlace de la partida copiado.');}catch{download('enlace-partida.txt',url);notice('Enlace guardado como archivo.');}break;}
 case 'export-battle':if(!battle)prepare();download('ogun-partida.json',JSON.stringify({type:'ogun-battle',...battle.original},null,2),'application/json');break;
 case 'import-battle':pickFile('.json',text=>{importBattle(JSON.parse(text));render();notice('Partida cargada con su semilla original.');});break;
 case 'upload-tournament':uploadTournament();break;
 case 'remove-upload':if(tournamentRunning)throw new Error('Detén el torneo antes de retirar participantes.');uploads=uploads.filter(w=>w.id!==el.dataset.id);tournamentSelection.delete(el.dataset.id);clampJornadas();saveSession();saveUploads();render();break;
 case 'tournament-examples':if(tournamentRunning)throw new Error('Detén el torneo antes de cambiar participantes.');D.warriors.slice(0,4).forEach(w=>tournamentSelection.add(w.id));clampJornadas();saveSession();saveUploads();render();break;
 case 'start-tournament':startTournament();break;
 case 'refresh-core':drawCore($('#core-canvas'),battle);break;
 case 'preview-win':showResult({winner:'A',a:'Mi guerrero',b:'Rival',reason:'El último proceso del rival ha terminado.'},'arena',true);break;
 case 'preview-draw':showResult({winner:'Empate',a:'Guerrero A',b:'Guerrero B',reason:'Ambos sobreviven al límite de turnos.'},'arena',true);break;
 case 'disable-motion':data.prefs.reduced=true;data.prefs.coreMotion=false;data.prefs.background='off';data.prefs.resultStyle='still';data.prefs.resultParticles=0;save();render();break;
 case 'announce-match':{const t=tournamentProgress||tournament,m=t.matches[+el.dataset.match];showResult({winner:m.outcome||'Empate',a:m.a,b:m.b,reason:`${m.aWins} – ${m.bWins} · ${m.draws} partidas empatadas`},'tournament');break;}
 case 'announce-game':{const t=tournamentProgress||tournament,m=t.matches[+el.dataset.match],g=m.games[+el.dataset.game];showResult({winner:g.winner,a:m.a,b:m.b,reason:g.reason},'tournament');break;}

 case 'cancel-tournament':dismissResult(true);if(worker)worker.terminate();worker=null;tournamentRunning=false;tournamentProgress=null;notice('Torneo detenido. No se guardan resultados parciales.');render();break;
 case 'export-tournament':if(tournament)download('ogun-torneo.json',JSON.stringify(tournament,null,2),'application/json');break;
 case 'open-tournament':assertLivePaused();liveTournament=null;tournament=structuredClone(data.tournaments[+el.dataset.index]);tournamentProgress=null;render();break;
 case 'replay-tournament':{const t=tournamentProgress||tournament,m=t.matches[+el.dataset.match],g=m.games[+el.dataset.game],a=t.entries.find(w=>w.id===m.aId),b=t.entries.find(w=>w.id===m.bId);if(!a||!b)throw new Error('No se encuentra el código de esta ronda.');replay({a:a.code,b:b.code,config:{...t.settings,seed:g.seed,firstWarrior:g.firstWarrior,loadPoints:g.positions}});break;}
 case 'export-data':checkpointLive();download('ogun-mis-datos.json',JSON.stringify({type:'ogun-backup',version:1,...data,liveTournament,workshopDraft:W.getDraft()},null,2),'application/json');break;
 case 'import-data':pickFile('.json',text=>{const raw=JSON.parse(text);if(raw.type!=='ogun-backup'||raw.version!==1)throw new Error('No es una copia de OGUN compatible.');const next=sanitize(raw),nextLive=Object.prototype.hasOwnProperty.call(raw,'liveTournament')?(raw.liveTournament===null?null:L.restore(raw.liveTournament)):liveTournament;if(raw.workshopDraft!==undefined&&(typeof raw.workshopDraft!=='string'||raw.workshopDraft.length>100000))throw new Error('Borrador del taller inválido.');if(!confirm('¿Reemplazar tus guerreros, progreso y resultados con esta copia?'))return;if(raw.workshopDraft!==undefined)W.restoreDraft(raw.workshopDraft);data=next;liveTournament=nextLive;liveRuntime=null;if(liveTournament)liveSave();else localStorage.removeItem('ogun_live_v1');saveSession();battle=null;tournament=null;tournamentProgress=null;if(worker)worker.terminate();worker=null;tournamentRunning=false;save();render();notice('Datos restaurados.');});break;
 case 'reset-prefs':data.prefs=structuredClone(defaults.prefs);save();render();break;
 }
}
function startTournament(){
 if(tournamentRunning)throw new Error('Ya hay un torneo en curso.');readTournamentDraft();clampJornadas();saveSession();const {rows,error}=validateParticipants();if(error)throw new Error(error);
 const requested=rows.filter(w=>tournamentSelection.has(w.id)),entries=requested.filter(w=>w.report.ok).map(({report,...w})=>w),excluded=requested.length-entries.length,settings=ruleSettings(),options=T.options(tournamentDraft,entries.length);
 for(let i=0;i<entries.length;i++)for(let j=i+1;j<entries.length;j++){const a=requested.find(w=>w.id===entries[i].id),b=requested.find(w=>w.id===entries[j].id);if(!T.compatible(a.report.length,b.report.length,settings))throw new Error(`No caben juntos ${a.name} y ${b.name}. Aumenta el núcleo o reduce la distancia mínima.`);}
 const seed=tournamentDraft.seed||String(crypto.getRandomValues(new Uint32Array(1))[0]),format=options.format,rounds=options.rounds,name=tournamentDraft.name.trim()||'Copa del núcleo';
 tournamentProgress={name,format,rounds,seed,entries:structuredClone(entries),settings:{...settings,drawPolicy:options.drawPolicy},options,rows:entries.map(w=>({id:w.id,name:w.name,points:0,wins:0,draws:0,losses:0,played:0,byes:0,buchholz:0,sonneborn:0,matchWins:0})),matches:[],stages:[],champion:null,leaders:[]};
 worker=new Worker('worker.js?v=1.3.0');tournamentRunning=true;saveUploads();
 worker.onmessage=({data:msg})=>{
 if(msg.type==='game'){if(data.prefs.tournamentFx==='games')showResult({winner:msg.result.winner,a:msg.a,b:msg.b,reason:msg.result.reason},'tournament');return;}
 if(msg.type==='error'){worker?.terminate();worker=null;tournamentRunning=false;tournamentProgress=null;notice('No se pudo completar el torneo: '+msg.message);if(route==='tournaments')render();return;}
 if(!tournamentProgress)return;const currentMatches=tournamentProgress.matches;tournamentProgress={...tournamentProgress,...msg,matches:msg.type==='progress'&&msg.lastMatch?[...currentMatches,msg.lastMatch]:msg.matches||currentMatches};
 if(msg.type==='complete'){
 tournament={...tournamentProgress,date:new Date().toISOString()};delete tournament.type;delete tournament.lastMatch;tournamentProgress=null;tournamentRunning=false;worker?.terminate();worker=null;data.tournaments.unshift(tournament);data.tournaments=data.tournaments.slice(0,10);save();notice('Torneo terminado. Resultados guardados.');if(route==='tournaments')render();announceTournament(tournament);
 }else{
 if(msg.lastMatch&&data.prefs.tournamentFx==='duels')showResult({winner:msg.lastMatch.outcome,a:msg.lastMatch.a,b:msg.lastMatch.b,reason:`${msg.lastMatch.aWins} – ${msg.lastMatch.bWins} · ${msg.lastMatch.draws} partidas empatadas`},'tournament');
 if($('#tournament-results'))$('#tournament-results').innerHTML=tournamentHTML();
 }
 };
 worker.onerror=()=>{worker?.terminate();worker=null;tournamentRunning=false;tournamentProgress=null;notice('No se pudo ejecutar el torneo en este navegador.');if(route==='tournaments')render();};
 worker.postMessage({entries,settings,options,rounds,format,seed});render();if(excluded)notice(`${excluded} guerreros rechazados han quedado fuera del torneo.`);
}
root.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;Promise.resolve().then(()=>action(button.dataset.action,button)).catch(e=>{if(['check-puzzle','validate-code'].includes(button.dataset.action)){if(button.dataset.action==='check-puzzle')setPuzzleFeedback(e.message,false);else $('#validation-'+button.dataset.side).textContent='✕ '+e.message;}else notice(e.message);running=false;});});
root.addEventListener('input',event=>{const el=event.target;W.input(el);if(el.id.startsWith('code-')){const id=el.id.slice(-1);W.arenaInput(id,el.value);data.draft[id]=el.value;running=false;battle=null;delete config.loadPoints;$('#validation-'+id).textContent='Código modificado. Vuelve a validarlo.';save();if($('#battle-result'))$('#battle-result').textContent='Código modificado. Inicia una nueva batalla.';if($('#run-btn'))$('#run-btn').textContent='▶ Iniciar batalla';}if(el.id==='inspect-index')inspect(+el.value);if(el.id==='warrior-search'){libraryFilter=el.value;const pos=el.selectionStart;render();$('#warrior-search').focus();$('#warrior-search').setSelectionRange(pos,pos);}});
root.addEventListener('change',event=>{const el=event.target;W.change(el);
 if(el.id==='live-auto'&&liveTournament){liveTournament.options.autoAdvance=el.checked;liveSave();}
 if(el.id==='live-speed'&&liveTournament){liveTournament.options.liveSpeed=+el.value;liveSave();}
 if(el.id==='live-edit-match'&&liveTournament){const r=L.view(liveTournament).matches.find(m=>m.id===el.value)?.result;$('#live-edit-a').value=r?.aWins??1;$('#live-edit-b').value=r?.bWins??0;$('#live-edit-draw').value=r?.draws??0;}
 if(el.id==='live-edit-person'&&liveTournament){$('#live-edit-owner').value=liveTournament.entries.find(e=>e.id===el.value)?.owner||'';$('#live-edit-points').value=liveTournament.adjustments[el.value]||0;}
 if(el.id.startsWith('select-')){const w=allWarriors().find(w=>w.id===el.value);if(w){data.draft[el.id.slice(-1)]=w.code;running=false;battle=null;save();render();}}
 if(el.id.startsWith('cfg-')){running=false;battle=null;delete config.loadPoints;try{readConfig();}catch(e){notice(e.message);}if($('#battle-result'))$('#battle-result').textContent='Reglas modificadas. Inicia una nueva batalla.';if($('#run-btn'))$('#run-btn').textContent='▶ Iniciar batalla';}
 if(el.id.startsWith('t-')){readTournamentDraft();if($('#participants'))$('#participants').innerHTML=participantsHTML();}
 if(el.id==='speed'){data.prefs.speed=+el.value;save();}
 if(el.id==='puzzle-date'){if(!/^\d{4}-\d{2}-\d{2}$/.test(el.value)||el.value>C.madridDate()){notice('Elige una fecha hasta hoy.');return;}puzzleDate=el.value;archiveMode=false;currentPuzzle=C.daily(puzzleDate,dailySlot);render();}
 if(el.id.startsWith('pref-')){const k=el.id.slice(5);data.prefs[k]=el.type==='checkbox'?el.checked:el.type==='color'?el.value:typeof S.DEFAULTS[k]==='number'?+el.value:el.value;if(k==='theme'){const colors={dark:['#b4f05a','#b299ff'],violet:['#79dfdb','#ffb782'],light:['#537c18','#7b43d3']}[el.value];data.prefs.a=colors[0];data.prefs.b=colors[1];}data.prefs=S.sanitize(data.prefs);applyPrefs();save();if($('#pref-value-'+k))$('#pref-value-'+k).textContent=data.prefs[k];if(k==='theme')render();}
 if(el.dataset.participant){if(tournamentRunning){el.checked=tournamentSelection.has(el.dataset.participant);notice('Detén el torneo antes de cambiar participantes.');return;}if(el.checked)tournamentSelection.add(el.dataset.participant);else tournamentSelection.delete(el.dataset.participant);clampJornadas();saveSession();saveUploads();if($('#participants'))$('#participants').innerHTML=participantsHTML();}
});
root.addEventListener('keydown',e=>{if(e.target.id==='answer'&&e.key==='Enter'){e.preventDefault();action('check-puzzle',e.target).catch(err=>setPuzzleFeedback(err.message,false));}if(e.target.id?.startsWith('code-')&&e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}});
window.addEventListener('hashchange',()=>{parseHash();if(route!=='tournaments')document.body.dataset.broadcast='false';render();scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});});
window.addEventListener('storage',event=>{if(event.key==='ogun-v1'){notice('Los datos han cambiado en otra pestaña. Exporta tu progreso antes de recargar si has hecho cambios aquí.');}});
setInterval(()=>{updateCountdown();const day=C.madridDate();if(day!==lastDay){if(puzzleDate===lastDay){puzzleDate=day;archiveMode=false;currentPuzzle=C.daily(day,dailySlot);if(route==='home'||route==='puzzles')render();}lastDay=day;}},30000);
for(const [type,name] of [['dragstart','start'],['dragover','over'],['drop','drop'],['dragend','end']])root.addEventListener(type,event=>W.drag(name,event));
function animate(time){W.tick(Date.now());if(resultActive&&resultDeadline&&Date.now()>=resultDeadline)dismissResult();if(time-frameTime>40){frameTime=time;try{tickLive(Date.now());}catch(e){if(liveRuntime){liveRuntime.resumePhase=liveRuntime.phase;liveRuntime.phase='paused';}checkpointLive();notice('Emisión pausada: '+e.message);renderLive();}if(route==='home'&&demo&&!data.prefs.reduced&&data.prefs.coreMotion&&!document.hidden){if(demo.halted)setupDemo();else E.runSteps(demo,12);drawCore($('#demo-canvas'),demo);if($('#demo-turns'))$('#demo-turns').textContent=`TURNO ${demo.cycle.toLocaleString('es')} / 1.024 CELDAS`;}if(route==='arena'&&running&&battle&&!document.hidden){E.runSteps(battle,data.prefs.speed);if(battle.halted)running=false;updateBattle();}}requestAnimationFrame(animate);}
document.addEventListener?.('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.dataset.broadcast='false';});
const resultLayer=$('#result-layer');
resultLayer?.addEventListener('click',e=>{const button=e.target.closest('[data-result]');if(button)dismissResult(button.dataset.result==='skip');else if(e.target===resultLayer)dismissResult(true);});
window.addEventListener('keydown',e=>{if(!resultActive)return;if(e.key==='Escape'){e.preventDefault();dismissResult(true);}else if(e.key==='Tab'){const first=$('#result-close'),last=$('#result-skip');if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
parseHash();render();requestAnimationFrame(animate);
if(storageIssue)notice('El guardado local no está disponible. Exporta tus datos antes de cerrar.');
if(liveRecoveryNotice)notice(liveRecoveryNotice);
})();
